package main

import (
	"gno.land/r/gov/dao"
	valv3 "gno.land/r/sys/validators/v3"
)

func main(cur realm) {
	r := valv3.NewValidatorProposalRequest(
		cross(cur),
		[]valv3.ValoperChange{
			valv3.NewValoperChange(address("g1kqdfj5ps9auyj5gzjwt079rlg6rpke9gspqudc"), 5),
			valv3.NewValoperChange(address("g1mndkvypn3339m6yvkyutal5hk6m2yeqp5d52ly"), 5),
			valv3.NewValoperChange(address("g1rac2pdlwjwsavxluvw7yc397luyr5grrf2mpl4"), 5),
		},
		"Add 3 validator(s) to the valset",
		"Batch-add 3 operator(s) to the active valset with voting power 5.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}

// Package bond is the create-bond policy for gnomemepad — separate from pad
// so promo schedules can change without redeploying the pad realm.
//
// Pad calls CurrentBondUgnot() at Create time. This package owns:
//   - normal bond (default 2 GNOT)
//   - promo bond (default ~$20 in ugnot at a fixed GNOT rate, admin-adjustable)
//   - 10-day window OR admin EndPromo → back to normal
//
// USD is not on-chain: promo amount is ugnot. Admin sets PromoBondUgnot to
// approximate $20 (e.g. at $1/GNOT → 20e6 ugnot; at $0.5/GNOT → 40e6).
package bond

import (
	"chain"
	"strconv"
	"time"
)

const (
	DenomUgnot = "ugnot"

	// Defaults (ugnot, 1 GNOT = 1e6 ugnot)
	DefaultNormalBondUgnot int64 = 2_000_000  // 2 GNOT
	DefaultPromoBondUgnot  int64 = 20_000_000 // 20 GNOT ≈ $20 if GNOT ≈ $1
	DefaultPromoDuration   int64 = 10 * 24 * 60 * 60 // 10 days (seconds)

	// Status for UI
	StatusNormal = 0
	StatusPromo  = 1
)

var (
	inited bool
	admin  address

	normalBondUgnot int64
	promoBondUgnot  int64
	// promo: active while time.Now().Unix() < promoEndsAt and !promoEnded
	promoEndsAt int64
	promoEnded  bool // admin force-end (or auto after window)
	promoStartedAt int64
)

// Init sets admin (deploy EOA) and default bond amounts. Call once.
func Init(cur realm) {
	if inited {
		panic("bond: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("bond: EOA only")
	}
	admin = cur.Previous().Address()
	normalBondUgnot = DefaultNormalBondUgnot
	promoBondUgnot = DefaultPromoBondUgnot
	promoEndsAt = 0
	promoEnded = true
	promoStartedAt = 0
	inited = true
	chain.Emit("Init", "admin", admin.String())
}

func requireInit() {
	if !inited {
		panic("bond: call Init first")
	}
}

func requireAdmin(cur realm) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("bond: EOA only")
	}
	if cur.Previous().Address() != admin {
		panic("bond: not admin")
	}
}

// Admin returns the admin (deploy) address.
func Admin() string {
	requireInit()
	return admin.String()
}

// TransferAdmin rotates admin (current admin only).
func TransferAdmin(cur realm, newAdmin address) {
	requireAdmin(cur)
	if !newAdmin.IsValid() {
		panic("bond: invalid address")
	}
	old := admin
	admin = newAdmin
	chain.Emit("TransferAdmin", "from", old.String(), "to", newAdmin.String())
}

// IsPromoActive reports whether the promo window is currently in force.
func IsPromoActive() bool {
	if !inited || promoEnded || promoEndsAt <= 0 {
		return false
	}
	now := time.Now().Unix()
	if now >= promoEndsAt {
		return false
	}
	return true
}

// CurrentBondUgnot is the create bond pad must require (cross-safe read).
// Pad: if sent < CurrentBondUgnot() → panic underpaid.
func CurrentBondUgnot() int64 {
	requireInit()
	if IsPromoActive() {
		return promoBondUgnot
	}
	return normalBondUgnot
}

// NormalBondUgnot returns the post-promo / default bond.
func NormalBondUgnot() int64 {
	requireInit()
	return normalBondUgnot
}

// PromoBondUgnot returns the promo-period bond amount (may be inactive).
func PromoBondUgnot() int64 {
	requireInit()
	return promoBondUgnot
}

// PromoEndsAt returns unix end of promo (0 if never started).
func PromoEndsAt() int64 {
	requireInit()
	return promoEndsAt
}

// PromoSecondsLeft returns remaining promo seconds (0 if inactive).
func PromoSecondsLeft() int64 {
	if !IsPromoActive() {
		return 0
	}
	left := promoEndsAt - time.Now().Unix()
	if left < 0 {
		return 0
	}
	return left
}

// Status: 0=normal 1=promo active.
func Status() int {
	if IsPromoActive() {
		return StatusPromo
	}
	return StatusNormal
}

// BondInfo: status|currentUgnot|normalUgnot|promoUgnot|endsAt|secondsLeft|admin
func BondInfo() string {
	requireInit()
	st := Status()
	return strconv.Itoa(st) + "|" +
		strconv.FormatInt(CurrentBondUgnot(), 10) + "|" +
		strconv.FormatInt(normalBondUgnot, 10) + "|" +
		strconv.FormatInt(promoBondUgnot, 10) + "|" +
		strconv.FormatInt(promoEndsAt, 10) + "|" +
		strconv.FormatInt(PromoSecondsLeft(), 10) + "|" +
		admin.String()
}

// StartPromo begins a promo window from now.
// promoUgnot: bond during promo (e.g. 20e6 ≈ $20 at $1/GNOT). 0 → keep current promoBondUgnot.
// durationSec: window length. 0 → DefaultPromoDuration (10 days).
func StartPromo(cur realm, promoUgnot, durationSec int64) {
	requireAdmin(cur)
	if promoUgnot < 0 {
		panic("bond: promoUgnot must be non-negative")
	}
	if promoUgnot > 0 {
		promoBondUgnot = promoUgnot
	}
	if promoBondUgnot <= 0 {
		panic("bond: set promo bond amount first")
	}
	if durationSec <= 0 {
		durationSec = DefaultPromoDuration
	}
	now := time.Now().Unix()
	promoStartedAt = now
	promoEndsAt = now + durationSec
	promoEnded = false
	chain.Emit("StartPromo",
		"promoUgnot", strconv.FormatInt(promoBondUgnot, 10),
		"endsAt", strconv.FormatInt(promoEndsAt, 10),
		"durationSec", strconv.FormatInt(durationSec, 10),
	)
}

// EndPromo forces normal bond immediately (deploy admin).
func EndPromo(cur realm) {
	requireAdmin(cur)
	promoEnded = true
	// keep promoEndsAt for history
	chain.Emit("EndPromo",
		"at", strconv.FormatInt(time.Now().Unix(), 10),
		"normalUgnot", strconv.FormatInt(normalBondUgnot, 10),
	)
}

// SetNormalBond updates the post-promo bond (default 2 GNOT).
func SetNormalBond(cur realm, ugnot int64) {
	requireAdmin(cur)
	if ugnot <= 0 {
		panic("bond: normal bond must be positive")
	}
	normalBondUgnot = ugnot
	chain.Emit("SetNormalBond", "ugnot", strconv.FormatInt(ugnot, 10))
}

// SetPromoBond updates promo amount without restarting the clock.
// Use to re-target ~$20 when GNOT price moves during the window.
func SetPromoBond(cur realm, ugnot int64) {
	requireAdmin(cur)
	if ugnot <= 0 {
		panic("bond: promo bond must be positive")
	}
	promoBondUgnot = ugnot
	chain.Emit("SetPromoBond", "ugnot", strconv.FormatInt(ugnot, 10))
}

// ExtendPromo adds seconds to the current end (or starts from now if inactive).
func ExtendPromo(cur realm, extraSec int64) {
	requireAdmin(cur)
	if extraSec <= 0 {
		panic("bond: extraSec must be positive")
	}
	now := time.Now().Unix()
	if !IsPromoActive() {
		// restart promo with current promoBondUgnot
		promoStartedAt = now
		promoEndsAt = now + extraSec
		promoEnded = false
	} else {
		promoEndsAt += extraSec
		promoEnded = false
	}
	chain.Emit("ExtendPromo",
		"endsAt", strconv.FormatInt(promoEndsAt, 10),
		"extraSec", strconv.FormatInt(extraSec, 10),
	)
}

package bond

import (
	"strconv"

	"gno.land/p/nt/ufmt/v0"
)

func Render(path string) string {
	_ = path
	out := "# gnomemepad create-bond policy\n\n"
	out += "Separate realm — pad upgrades do not replace this schedule.\n\n"
	if !inited {
		out += "> [!CAUTION]\n> Call Init first.\n"
		return out
	}
	out += ufmt.Sprintf("- **Current bond:** %d ugnot (~%d GNOT)\n", CurrentBondUgnot(), CurrentBondUgnot()/1_000_000)
	out += ufmt.Sprintf("- **Normal bond:** %d ugnot\n", normalBondUgnot)
	out += ufmt.Sprintf("- **Promo bond:** %d ugnot\n", promoBondUgnot)
	if IsPromoActive() {
		out += ufmt.Sprintf("- **Promo active** — ends at unix %d (~%d s left)\n", promoEndsAt, PromoSecondsLeft())
	} else {
		out += "- Promo: inactive (using normal bond)\n"
	}
	out += ufmt.Sprintf("- Admin: `%s`\n\n", admin.String())
	out += "## API\n\n"
	out += "- `CurrentBondUgnot()` — pad reads this on Create\n"
	out += "- `StartPromo(promoUgnot, durationSec)` — admin; 0 amount keeps set promo bond; 0 duration → 10d\n"
	out += "- `EndPromo()` — admin → normal bond immediately\n"
	out += "- `SetNormalBond` / `SetPromoBond` / `ExtendPromo`\n"
	out += "- `BondInfo()` → status|current|normal|promo|endsAt|left|admin\n"
	_ = strconv.Itoa(0)
	return out
}

// Package ammmath implements integer bonding-curve and constant-product AMM
// helpers for the gnomemepad factory (Pump-style virtual CPMM + real CPMM pool).
package ammmathv2

import "math/overflow"

// FeeResult is the split of a gross trade fee.
type FeeResult struct {
	Gross     int64
	Net       int64
	Fee       int64
	Creator   int64
	Protocol  int64
	Remainder int64
}

// ApplyFee takes gross quote paid by the user and feeBPS (e.g. 120 = 1.20%).
func ApplyFee(gross, feeBPS, creatorShareBPS, protocolShareBPS int64) FeeResult {
	if gross <= 0 {
		panic("ammmath: gross must be positive")
	}
	if feeBPS < 0 || feeBPS >= 10000 {
		panic("ammmath: feeBPS out of range")
	}
	if creatorShareBPS < 0 || protocolShareBPS < 0 || creatorShareBPS+protocolShareBPS > 10000 {
		panic("ammmath: fee share BPS invalid")
	}
	fee := gross * feeBPS / 10000
	net := gross - fee
	creator := fee * creatorShareBPS / 10000
	protocol := fee * protocolShareBPS / 10000
	remainder := fee - creator - protocol
	return FeeResult{
		Gross:     gross,
		Net:       net,
		Fee:       fee,
		Creator:   creator,
		Protocol:  protocol,
		Remainder: remainder,
	}
}

// ApplyFeeOnOutput charges fee on assets leaving the pool/curve.
func ApplyFeeOnOutput(grossOut, feeBPS, creatorShareBPS, protocolShareBPS int64) FeeResult {
	if grossOut <= 0 {
		panic("ammmath: grossOut must be positive")
	}
	if feeBPS < 0 || feeBPS >= 10000 {
		panic("ammmath: feeBPS out of range")
	}
	if creatorShareBPS < 0 || protocolShareBPS < 0 || creatorShareBPS+protocolShareBPS > 10000 {
		panic("ammmath: fee share BPS invalid")
	}
	fee := grossOut * feeBPS / 10000
	net := grossOut - fee
	if net <= 0 {
		panic("ammmath: fee consumes entire output")
	}
	creator := fee * creatorShareBPS / 10000
	protocol := fee * protocolShareBPS / 10000
	remainder := fee - creator - protocol
	return FeeResult{
		Gross:     grossOut,
		Net:       net,
		Fee:       fee,
		Creator:   creator,
		Protocol:  protocol,
		Remainder: remainder,
	}
}

// BuyTokens quotes a virtual constant-product buy (net ugnot in).
func BuyTokens(virtualUgnot, virtualToken, ugnotIn int64) (tokensOut, newVU, newVT int64) {
	if ugnotIn <= 0 {
		panic("ammmath: ugnotIn must be positive")
	}
	if virtualUgnot <= 0 || virtualToken <= 0 {
		panic("ammmath: invalid virtual reserves")
	}
	newVU, ok := overflow.Add64(virtualUgnot, ugnotIn)
	if !ok {
		panic("ammmath: virtual ugnot overflow")
	}
	k, ok := overflow.Mul64(virtualUgnot, virtualToken)
	if !ok {
		panic("ammmath: k overflow")
	}
	newVT = k / newVU
	if newVT <= 0 {
		panic("ammmath: empty virtual token reserve")
	}
	if newVT >= virtualToken {
		panic("ammmath: zero tokens out")
	}
	tokensOut = virtualToken - newVT
	return tokensOut, newVU, newVT
}

// MaxNetInForTokenOut is the largest net ugnot in that yields tokensOut â‰¤ maxTokensOut
// (integer CPMM, same floor rules as BuyTokens). Used to fill the last curve tokens
// without panicking when the user sends too much GNOT.
func MaxNetInForTokenOut(virtualUgnot, virtualToken, maxTokensOut int64) int64 {
	if maxTokensOut <= 0 || virtualUgnot <= 0 || virtualToken <= 0 {
		return 0
	}
	if maxTokensOut >= virtualToken {
		return 0
	}
	targetNewVT := virtualToken - maxTokensOut
	k, ok := overflow.Mul64(virtualUgnot, virtualToken)
	if !ok {
		panic("ammmath: k overflow")
	}
	// tokensOut â‰¤ max  â‡”  k/(vu+net) â‰¥ targetNewVT  â‡”  vu+net â‰¤ k/targetNewVT (floor)
	maxNewVU := k / targetNewVT
	if maxNewVU <= virtualUgnot {
		return 0
	}
	return maxNewVU - virtualUgnot
}

// SellTokens quotes a virtual constant-product sell (gross ugnot out).
func SellTokens(virtualUgnot, virtualToken, tokensIn int64) (ugnotOut, newVU, newVT int64) {
	if tokensIn <= 0 {
		panic("ammmath: tokensIn must be positive")
	}
	if virtualUgnot <= 0 || virtualToken <= 0 {
		panic("ammmath: invalid virtual reserves")
	}
	newVT, ok := overflow.Add64(virtualToken, tokensIn)
	if !ok {
		panic("ammmath: virtual token overflow")
	}
	k, ok := overflow.Mul64(virtualUgnot, virtualToken)
	if !ok {
		panic("ammmath: k overflow")
	}
	newVU = k / newVT
	if newVU <= 0 {
		panic("ammmath: empty virtual ugnot reserve")
	}
	if newVU >= virtualUgnot {
		panic("ammmath: zero ugnot out")
	}
	ugnotOut = virtualUgnot - newVU
	return ugnotOut, newVU, newVT
}

// PoolSwapUgnotForToken swaps net ugnot for tokens; remainderToPool adds to ugnot reserve.
func PoolSwapUgnotForToken(poolUgnot, poolToken, ugnotIn, remainderToPool int64) (tokensOut, newPU, newPT int64) {
	if ugnotIn <= 0 {
		panic("ammmath: ugnotIn must be positive")
	}
	if poolUgnot <= 0 || poolToken <= 0 {
		panic("ammmath: invalid pool reserves")
	}
	if remainderToPool < 0 {
		panic("ammmath: negative remainder")
	}
	addU, ok := overflow.Add64(ugnotIn, remainderToPool)
	if !ok {
		panic("ammmath: add overflow")
	}
	newPU, ok = overflow.Add64(poolUgnot, addU)
	if !ok {
		panic("ammmath: pool ugnot overflow")
	}
	tokensOut = poolToken * ugnotIn / (poolUgnot + ugnotIn)
	if tokensOut <= 0 {
		panic("ammmath: zero tokens out of pool")
	}
	if tokensOut >= poolToken {
		panic("ammmath: would drain pool tokens")
	}
	newPT = poolToken - tokensOut
	return tokensOut, newPU, newPT
}

// PoolSwapTokenForUgnot swaps tokens for gross ugnot out.
func PoolSwapTokenForUgnot(poolUgnot, poolToken, tokensIn int64) (ugnotOut, newPU, newPT int64) {
	if tokensIn <= 0 {
		panic("ammmath: tokensIn must be positive")
	}
	if poolUgnot <= 0 || poolToken <= 0 {
		panic("ammmath: invalid pool reserves")
	}
	newPT, ok := overflow.Add64(poolToken, tokensIn)
	if !ok {
		panic("ammmath: pool token overflow")
	}
	ugnotOut = poolUgnot * tokensIn / (poolToken + tokensIn)
	if ugnotOut <= 0 {
		panic("ammmath: zero ugnot out of pool")
	}
	if ugnotOut >= poolUgnot {
		panic("ammmath: would drain pool ugnot")
	}
	newPU = poolUgnot - ugnotOut
	return ugnotOut, newPU, newPT
}

// CanGraduate reports whether raised net ugnot meets the threshold.
func CanGraduate(raisedUgnot, threshold int64) bool {
	return raisedUgnot >= threshold && threshold > 0
}

// SpotPriceUgnotPerToken returns ugnot per token scaled by 1e6 (display only).
func SpotPriceUgnotPerToken(ugnotReserve, tokenReserve int64) int64 {
	if tokenReserve <= 0 {
		return 0
	}
	return ugnotReserve * 1000000 / tokenReserve
}

package padv9

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/p/gnoswap/consts"
	u256 "gno.land/p/gnoswap/uint256"
	"gno.land/r/gnoland/wugnot"
	"gno.land/r/gnoswap/gns"
	gnspool "gno.land/r/gnoswap/pool"
	"gno.land/r/gnoswap/position"
	"gno.land/r/gnoswap/router"
)

// Sapphire Gnoswap registry keys / role addresses (sapphire-1).
const (
	wugnotTokenKey       = "gno.land/r/gnoland/wugnot.wugnot"
	gnsTokenKey          = "gno.land/r/gnoswap/gns.GNS"
	gnoswapPoolAddrStr   = "g1dexaf6aqkkyr9yfy9d5up69lsn7ra80af34g5v"
	gnoswapRouterAddrStr = "g1vc883gshu5z7ytk5cdynhc8c2dh67pdp4cszkp"
)

// tryListOnGnoswap seeds a Gnoswap CL pool with remaining meme tokens + raised-sized
// WUGNOT as LP. CreatePool fee (fixed GNS amount) is paid from:
//  1) pre-funded GNS on pad (preferred â€” immune to GNOT/GNS price moves), else
//  2) ExactOut WUGNOTâ†’GNS using SURPLUS inventory only (above raised), so LP depth
//     stays equal to raised even when GNS is expensive.
//
// Returns true on success. Soft failure sets l.GnoswapNote and returns false
// (caller keeps internal CPMM).
//
// Note: wugnot.Deposit is EOA-only â€” protocol must pre-fund pad with WUGNOT
// (and ideally GNS). Raised ugnot stays on pad as wrap-back backlog.
func tryListOnGnoswap(cur realm, l *Launch, raisedUgnot, remainingTokens int64) bool {
	if raisedUgnot <= 0 || remainingTokens <= 0 {
		l.GnoswapNote = "list skip: empty capital"
		return false
	}
	padAddr := cur.Address()
	wBal := wugnot.BalanceOf(padAddr)
	if wBal < raisedUgnot {
		l.GnoswapNote = "list skip: need WUGNOT inventory >= raised for LP; have " +
			strconv.FormatInt(wBal, 10) + " need " + strconv.FormatInt(raisedUgnot, 10)
		return false
	}

	feeNeed := gnspool.GetPoolCreationFee()
	if feeNeed <= 0 {
		feeNeed = 100_000_000 // 100 GNS default (6 decimals)
	}

	// --- GNS for CreatePool fee (price-sensitive only if we must swap) ---
	gnsBal := gns.BalanceOf(padAddr)
	feeWugnot := int64(0)
	if gnsBal < feeNeed {
		// Fee paid from inventory ABOVE raised so LP size stays = raised.
		// maxIn = min(GnoswapMaxFeeWugnot, surplus) â€” NOT raised/2 (that blocked list at ~10 GNOT/GNS).
		surplus := wBal - raisedUgnot
		if surplus < 1 {
			l.GnoswapNote = "list skip: need GNS on pad or WUGNOT surplus above raised for fee swap; " +
				"CreatePool fee is fixed GNS â€” cost in GNOT moves with market (~1k GNOT/100 GNS at ~10:1)"
			return false
		}
		maxFeeW := GnoswapMaxFeeWugnot
		if maxFeeW > surplus {
			maxFeeW = surplus
		}
		if maxFeeW < 1 {
			l.GnoswapNote = "list skip: fee WUGNOT budget empty"
			return false
		}
		spent, ok := swapWugnotForGNS(cur, feeNeed, maxFeeW)
		if !ok {
			l.GnoswapNote = "list skip: WUGNOTâ†’GNS ExactOut failed (price too high for budget " +
				strconv.FormatInt(maxFeeW, 10) + " ugnot, or thin liquidity). " +
				"Pre-fund " + strconv.FormatInt(feeNeed, 10) + " GNS base units or more WUGNOT surplus."
			return false
		}
		feeWugnot = spent
		gnsBal = gns.BalanceOf(padAddr)
		if gnsBal < feeNeed {
			l.GnoswapNote = "list skip: GNS still short after swap"
			return false
		}
		// Protect LP: after fee spend we must still hold >= raised WUGNOT.
		if wugnot.BalanceOf(padAddr) < raisedUgnot {
			l.GnoswapNote = "list skip: fee swap ate into LP inventory (should not happen with surplus cap)"
			return false
		}
	}

	// LP always seeds full raised-sized WUGNOT (fee never reduces LP when surplus/GNS used).
	liqWugnot := raisedUgnot
	if wugnot.BalanceOf(padAddr) < liqWugnot {
		l.GnoswapNote = "list skip: WUGNOT below raised after fee path"
		return false
	}

	// Mint remaining GRC20 to pad for position.Mint TransferFrom.
	addBal(l, padAddr, remainingTokens)

	tokenKey := adenaKeyFromTokenID(l.TokenID, l.Symbol)
	if tokenKey == "" {
		l.GnoswapNote = "list skip: empty token registry key"
		return false
	}

	// Order tokens lexicographically (Gnoswap requirement).
	t0, t1 := wugnotTokenKey, tokenKey
	amt0, amt1 := liqWugnot, remainingTokens
	if strings.Compare(t0, t1) > 0 {
		t0, t1 = t1, t0
		amt0, amt1 = amt1, amt0
	}

	sqrtPrice := computeSqrtPriceX96(amt0, amt1)
	if sqrtPrice == "" || sqrtPrice == "0" {
		l.GnoswapNote = "list skip: bad sqrtPriceX96"
		return false
	}

	// Approve pool for GNS creation fee + both LP legs.
	poolAddr := address(gnoswapPoolAddrStr)
	gns.Approve(cross(cur), poolAddr, feeNeed)
	wugnot.Approve(cross(cur), poolAddr, liqWugnot)
	if err := l.ledger.Approve(padAddr, poolAddr, remainingTokens); err != nil {
		l.GnoswapNote = "list skip: token approve failed: " + err.Error()
		return false
	}

	// CreatePool (factory reorders tokens + inverts price if needed).
	gnspool.CreatePool(cross(cur), wugnotTokenKey, tokenKey, GnoswapFeeTier, sqrtPrice)

	tickLower, tickUpper := alignedFullRangeTicks(GnoswapTickSpacing)
	deadline := time.Now().Unix() + 600

	posID, liqStr, a0, a1 := position.Mint(
		cross(cur),
		t0,
		t1,
		GnoswapFeeTier,
		tickLower,
		tickUpper,
		strconv.FormatInt(amt0, 10),
		strconv.FormatInt(amt1, 10),
		"0",
		"0",
		deadline,
		padAddr, // permanent lock: pad owns position NFT
		"",
	)

	poolPath := t0 + ":" + t1 + ":" + strconv.FormatUint(uint64(GnoswapFeeTier), 10)
	l.GnoswapListed = true
	l.GnoswapPoolPath = poolPath
	l.GnoswapPositionID = posID
	l.FeeWugnotSpent = feeWugnot
	l.LiqWugnotUsed = liqWugnot
	l.GnoswapNote = "listed pool=" + poolPath + " pos=" + strconv.FormatUint(posID, 10) +
		" liq=" + liqStr + " a0=" + a0 + " a1=" + a1 +
		" feeWugnot=" + strconv.FormatInt(feeWugnot, 10)

	chain.Emit("GnoswapListed",
		"id", l.ID,
		"poolPath", poolPath,
		"positionId", strconv.FormatUint(posID, 10),
		"feeWugnot", strconv.FormatInt(feeWugnot, 10),
		"liqWugnot", strconv.FormatInt(liqWugnot, 10),
		"tokens", strconv.FormatInt(remainingTokens, 10),
	)
	return true
}

// swapWugnotForGNS ExactOut-swaps WUGNOTâ†’GNS. maxInWugnot is a hard ceiling
// (slippage / price protection): if market needs more GNOT for amountOutGNS, swap reverts.
func swapWugnotForGNS(cur realm, amountOutGNS, maxInWugnot int64) (spent int64, ok bool) {
	if amountOutGNS <= 0 || maxInWugnot <= 0 {
		return 0, false
	}
	routerAddr := address(gnoswapRouterAddrStr)
	before := wugnot.BalanceOf(cur.Address())
	if before < maxInWugnot {
		maxInWugnot = before
	}
	if maxInWugnot <= 0 {
		return 0, false
	}
	wugnot.Approve(cross(cur), routerAddr, maxInWugnot)

	route := wugnotTokenKey + ":" + gnsTokenKey + ":" + strconv.FormatUint(uint64(GnoswapFeeTier), 10)
	deadline := time.Now().Unix() + 600
	// ExactOut panics on insufficient maxIn â€” recover as soft fail for graduate fallback.
	// Gno has no recover in production the same way; ExactOut reverts the whole tx if over maxIn.
	// Callers must set maxIn high enough. We still try; panic would revert graduate entirely.
	// Prefer pre-funded GNS to avoid this path under volatile prices.
	inStr, outStr := router.ExactOutSwapRoute(
		cross(cur),
		wugnotTokenKey,
		gnsTokenKey,
		strconv.FormatInt(amountOutGNS, 10),
		route,
		"100",
		strconv.FormatInt(maxInWugnot, 10),
		deadline,
		"",
	)
	_ = outStr
	spentIn, err := strconv.ParseInt(inStr, 10, 64)
	if err != nil || spentIn <= 0 {
		after := wugnot.BalanceOf(cur.Address())
		if after >= before {
			return 0, false
		}
		return before - after, true
	}
	return spentIn, true
}

// computeSqrtPriceX96 returns sqrt(amount1/amount0) * 2^96 as decimal string.
func computeSqrtPriceX96(amount0, amount1 int64) string {
	if amount0 <= 0 || amount1 <= 0 {
		return ""
	}
	a0 := u256.MustFromDecimal(strconv.FormatInt(amount0, 10))
	a1 := u256.MustFromDecimal(strconv.FormatInt(amount1, 10))
	num := u256.Zero().Mul(a1, consts.Q192())
	ratio := u256.Zero().Div(num, a0)
	sqrt := u256Sqrt(ratio)
	if sqrt.Lt(consts.MinSqrtRatio()) {
		return consts.MinSqrtRatio().ToString()
	}
	if sqrt.Gte(consts.MaxSqrtRatio()) {
		return u256.Zero().Sub(consts.MaxSqrtRatio(), u256.One()).ToString()
	}
	return sqrt.ToString()
}

func u256Sqrt(x *u256.Uint) *u256.Uint {
	if x == nil || x.IsZero() {
		return u256.Zero()
	}
	if x.Eq(u256.One()) {
		return u256.One()
	}
	lo := u256.Zero()
	hi := u256.Zero().Add(x, u256.One())
	cap128 := u256.Zero().Lsh(u256.One(), 128)
	if hi.Gt(cap128) {
		hi = cap128.Clone()
	}
	for lo.Lt(u256.Zero().Sub(hi, u256.One())) {
		mid := u256.Zero().Div(u256.Zero().Add(lo, hi), u256.NewUint(2))
		if mid.IsZero() {
			lo = u256.One()
			continue
		}
		sq, overflow := u256.Zero().MulOverflow(mid, mid)
		if overflow || sq.Gt(x) {
			hi = mid
		} else {
			lo = mid
		}
	}
	return lo
}

func alignedFullRangeTicks(spacing int32) (int32, int32) {
	if spacing <= 0 {
		spacing = 60
	}
	tl := (GnoswapMinTick / spacing) * spacing
	tu := (GnoswapMaxTick / spacing) * spacing
	if tl >= tu {
		tl = -spacing
		tu = spacing
	}
	return tl, tu
}

