type Bytes []byte

func (bz Bytes) String() string {
	return "0x" + hex.EncodeToString(bz)
}

func (bz Bytes) Bytes() []byte {
	out := make([]byte, len(bz))
	copy(out, bz)

	return out
}

// Clone returns a fresh Bytes detached from any external/readonly realm
// ownership of bz.
//
// Under gno's InterRealm v2 borrow rules a value that crossed a realm boundary
// is externally stored, and a direct slice->slice conversion of it (a plain
// types.Bytes->[]byte cast, or a []byte->string->[]byte round-trip, which gno
// elides) keeps the foreign ownership and panics with "illegal conversion of
// readonly or externally stored value" when later stored or re-emitted. copy is
// an element-wise read, not a conversion, so it is permitted on a readonly
// source and yields a value owned by the caller's realm. Use Clone before
// persisting or re-emitting Bytes that arrived from another realm.
func (bz Bytes) Clone() Bytes {
	return Bytes(bz.Bytes())
}

// CloneBytes returns a fresh copy of b, or nil for nil input. It is the []byte
// counterpart of Bytes.Clone: realm packages use it to detach the InterRealm v2
// ownership of a slice that crossed a realm boundary before storing or
// re-emitting it. copy is an element-wise read (permitted on a foreign/readonly
// slice); a slice->slice conversion or a []byte->string->[]byte round-trip (which
// gno elides) would keep the foreign ownership and later panic with "illegal
// conversion of readonly or externally stored value".
func CloneBytes(b []byte) []byte {
	if b == nil {
		return nil
	}

	out := make([]byte, len(b))
	copy(out, b)

	return out
}

type H256 [32]byte

func (h H256) String() string {
	return "0x" + hex.EncodeToString(h[:])
}

type ClientType string

func (ct ClientType) String() string {
	return string(ct)
}

// Package app defines the IBC application callback contract that core invokes.
// The interface lives in a pure package so application realms can implement it
// without importing core, and core can route packets to them by interface
// (dependency inversion: app imports core, core depends only on this contract).
package app

import "gno.land/p/onbloc/ibc/union/types"

// IApp defines the interface for IBC application callbacks. Byte parameters
// use plain []byte (not the typed Bytes wrapper) so foreign-realm apps can
// implement the interface without the cross(cur)-realm typed-slice pitfall.
type IApp interface {
	OnChannelOpenInit(cur realm, connectionId types.ConnectionId, channelId types.ChannelId, version string, relayer address)
	OnChannelOpenTry(cur realm, connectionId types.ConnectionId, channelId types.ChannelId, version string, counterpartyVersion string, relayer address)
	OnChannelOpenAck(cur realm, channelId types.ChannelId, counterpartyChannelId types.ChannelId, counterpartyVersion string, relayer address)
	OnChannelOpenConfirm(cur realm, channelId types.ChannelId, relayer address)
	OnChannelCloseInit(cur realm, channelId types.ChannelId, relayer address)
	OnChannelCloseConfirm(cur realm, channelId types.ChannelId, relayer address)
	OnRecvPacket(cur realm, packet types.Packet, relayer address, relayerMsg []byte) types.RecvPacketResult
	OnAcknowledgementPacket(cur realm, packet types.Packet, acknowledgement []byte, relayer address)
	OnTimeoutPacket(cur realm, packet types.Packet, relayer address)

	IIntentApp
}

// IIntentApp is implemented by apps that explicitly support the proofless
// market-maker intent receive path.
type IIntentApp interface {
	OnIntentRecvPacket(cur realm, packet types.Packet, marketMaker address, marketMakerMsg []byte) types.RecvPacketResult
}

package lightclient

import "gno.land/p/onbloc/ibc/union/types"

// ClientImpl is the registered light client implementation for a client type.
// It mirrors Union's ClientRegistry value: Union stores a client contract
// address, while this Gno core stores a constructor function that instantiates
// the live light client for a submitted client state.
// Union references:
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/core/src/contract.rs#L849-L865
type ClientImpl func(clientStateBytes, consensusStateBytes []byte) (Interface, error)

type Status string

const (
	Active Status = "Active"

	Frozen Status = "Frozen"

	Expired Status = "Expired"

	Unknown Status = "Unknown"

	Unauthorized Status = "Unauthorized"
)

func (s Status) ToType() types.Status {
	switch s {
	case Active:
		return types.StatusActive
	case Expired:
		return types.StatusExpired
	case Frozen:
		return types.StatusFrozen
	default:
		return types.StatusUnknown
	}
}

type Interface interface {
	VerifyMembership(height uint64, key []byte, proof []byte, value []byte) error

	VerifyNonMembership(height uint64, key []byte, proof []byte) error

	GetTimestamp() types.Timestamp

	// GetTimestampAtHeight returns the consensus timestamp recorded at a specific
	// height. Packet timeout verification needs the counterparty timestamp at the
	// proof height, not just the latest. Returns an error when no consensus state
	// exists at the height.
	GetTimestampAtHeight(height uint64) (types.Timestamp, error)

	GetLatestHeight() uint64

	GetCounterpartyChainID() string

	Status() Status

	VerifyHeader(caller address, header []byte, relayer address) (types.StateUpdate, error)

	VerifyCreation(caller address, relayer address) (types.ClientCreationResult, error)

	Misbehaviour(caller address, misbehaviour []byte, relayer address) ([]byte, error)
