import u256 "gno.land/p/onbloc/math/uint256"

// Zkgmable is implemented by realms that receive ZKGM Call instructions
// dispatched from the ZKGM proxy.
type Zkgmable interface {
	// OnZkgm handles a standard ZKGM Call.
	OnZkgm(cur realm, env CallEnv) error

	// OnIntentZkgm handles the intent-settlement Call variant.
	OnIntentZkgm(cur realm, env IntentCallEnv) error
}

type CallEnv struct {
	Caller             string
	ProxyAccount       string
	Path               *u256.Uint
	SourceChannel      string
	DestinationChannel string
	Sender             []byte
	Calldata           []byte
	Relayer            []byte
	RelayerMsg         []byte
}

type IntentCallEnv struct {
	Caller             string
	ProxyAccount       string
	Path               *u256.Uint
	SourceChannel      string
	DestinationChannel string
	Sender             []byte
	Calldata           []byte
	MarketMaker        []byte
	MarketMakerMsg     []byte
}

package zkgm

import (
	"errors"

	u256 "gno.land/p/onbloc/math/uint256"
)

// ErrChannelPathFull is returned by UpdateChannelPath when the path can no
// longer hold another hop.
var ErrChannelPathFull = errors.New("zkgm: channel path is full")

// ErrNonCanonicalPath is returned when a channel path has a zero-value slot
// below HopCount(path).
var ErrNonCanonicalPath = errors.New("zkgm: channel path is not canonical")

const (
	channelIDMask  = uint64(0xFFFFFFFF)
	channelSlotBit = uint(32)
	maxHopIndex    = 7
	// MaxHops is the largest number of channel hops a path can encode.
	// Mirrors the maxHopIndex+1 invariant enforced by UpdateChannelPath.
	MaxHops = maxHopIndex + 1
)

func channelIDMaskU256() *u256.Uint { return u256.NewUint(channelIDMask) }

// DequeueChannelFromPath pops the lowest 32-bit channel slot off the path and
// shifts the remainder right. Returns the truncated path and the popped
// channel ID. A channel ID of 0 means the path was empty.
//
// Based on Union's `dequeue_channel_from_path` path helper.
func DequeueChannelFromPath(path *u256.Uint) (*u256.Uint, uint32) {
	if path.IsZero() {
		return u256.Zero(), 0
	}

	newPath := u256.Zero().Rsh(path, channelSlotBit)
	low := u256.Zero().And(path, channelIDMaskU256())

	return newPath, uint32(low.Uint64())
}

// PopChannelFromPath extracts the highest non-zero 32-bit channel slot from
// the path, returning the path with that slot cleared and the popped channel
// ID. A channel ID of 0 means the path was empty.
//
// Based on Union's `pop_channel_from_path` path helper.
func PopChannelFromPath(path *u256.Uint) (*u256.Uint, uint32) {
	if path.IsZero() {
		return u256.Zero(), 0
	}

	highestIndex := uint(path.BitLen()-1) / channelSlotBit
	channelID := GetChannelFromPath(path, int(highestIndex))

	slotMask := u256.Zero().Lsh(channelIDMaskU256(), highestIndex*channelSlotBit)
	basePath := u256.Zero().AndNot(path, slotMask)

	return basePath, channelID
}

// UpdateChannelPath appends nextChannelID to the path at the next free
// 32-bit slot. Returns ErrChannelPathFull when the path can no longer hold
// another hop.
//
// Uses the occupied slot count so full-width 32-bit channel IDs still append
// to the immediately next slot instead of skipping an aligned bit boundary.
func UpdateChannelPath(path *u256.Uint, nextChannelID uint32) (*u256.Uint, error) {
	if path.IsZero() {
		return u256.NewUint(uint64(nextChannelID)), nil
	}

	nextHopIndex := HopCount(path)
	if nextHopIndex > maxHopIndex {
		return nil, ErrChannelPathFull
	}

	slot := MakePathFromChannel(nextChannelID, nextHopIndex)

	return u256.Zero().Or(slot, path), nil
}

// GetChannelFromPath returns the channel ID stored at the given 32-bit slot
// (0-indexed from the LSB). Returns 0 if the slot is empty or out of range.
//
// Based on Union's `get_channel_from_path` path helper.
func GetChannelFromPath(path *u256.Uint, index int) uint32 {
	if index < 0 {
		return 0
	}

	shifted := u256.Zero().Rsh(path, uint(index)*channelSlotBit)
	masked := u256.Zero().And(shifted, channelIDMaskU256())

	return uint32(masked.Uint64())
}

// HopCount returns the number of 32-bit channel slots occupied by path.
// A nil or zero path has zero hops.
func HopCount(path *u256.Uint) int {
	if path == nil || path.IsZero() {
		return 0
	}

	return (path.BitLen() + int(channelSlotBit) - 1) / int(channelSlotBit)
}

// IsCanonicalPath reports whether all occupied channel slots are contiguous.
func IsCanonicalPath(path *u256.Uint) bool {
	hops := HopCount(path)
	for i := 0; i < hops; i++ {
		if GetChannelFromPath(path, i) == 0 {
			return false
		}
	}

	return true
}

// MakePathFromChannel builds a path containing channelID at the given slot.
//
// Based on Union's `make_path_from_channel` path helper.
func MakePathFromChannel(channelID uint32, index int) *u256.Uint {
	if index < 0 {
		return u256.Zero()
	}

	return u256.Zero().Lsh(u256.NewUint(uint64(channelID)), uint(index)*channelSlotBit)
}

// ReverseChannelPath returns a path with the same channel hops in reversed
// order. Returns ErrNonCanonicalPath if path has a gap below its occupied
// slots, or ErrChannelPathFull when the reversed path would overflow.
//
// Callers already pass canonical paths; the check guards future callers.
//
// Based on Union's `reverse_channel_path` path helper.
func ReverseChannelPath(path *u256.Uint) (*u256.Uint, error) {
	if !IsCanonicalPath(path) {
		return nil, ErrNonCanonicalPath
	}

	reversed := u256.Zero()

	cur := path
	for hops := 0; hops < MaxHops; hops++ {
		tail, head := PopChannelFromPath(cur)
		if head != 0 {
			updated, err := UpdateChannelPath(reversed, head)
			if err != nil {
				return nil, err
			}

			reversed = updated
		}

		if tail.IsZero() {
			return reversed, nil
		}

		cur = tail
	}
	// A valid uint256 path has at most MaxHops 32-bit slots. Reaching this
	// branch means the path invariant was violated before the tail was consumed.
	return nil, ErrChannelPathFull
}

package zkgm

import (
	"crypto/keccak256"
	"encoding/binary"
	"encoding/hex"

	abi "gno.land/p/onbloc/encoding/abi"
	types "gno.land/p/onbloc/ibc/union/types"
	u256 "gno.land/p/onbloc/math/uint256"
)

const (
	ibcDenomPrefix         = "ibc/"
	tagCallProxy           = "ZKGM_CALL_PROXY"
	callProxyAccountPrefix = "zkgm1"
)

// PredictWrappedToken derives the legacy wrapped IBC denom for a v1 token order.
func PredictWrappedToken(path *u256.Uint, channelId uint32, baseToken []byte) string {
	if path == nil {
		path = u256.Zero()
	}

	bz, err := abi.Encode(PredictWrappedTokenSchema, []any{path, channelId, baseToken})
	if err != nil {
		panic(err)
	}

	h := keccak256.Sum256(bz)

	return ibcDenomPrefix + hex.EncodeToString(h[:20])
}

// PredictWrappedTokenV2 derives the IBC voucher denom for a v2 token order.
func PredictWrappedTokenV2(path *u256.Uint, channelId uint32, baseToken []byte, metadataImage [32]byte) string {
	if path == nil {
		path = u256.Zero()
	}

	image := u256.Zero().SetBytes(metadataImage[:])

	bz, err := abi.Encode(PredictV2Schema, []any{path, channelId, baseToken, image})
	if err != nil {
		panic(err)
	}

	h := keccak256.Sum256(bz)

	return ibcDenomPrefix + hex.EncodeToString(h[:20])
}

// MetadataImage returns keccak256(TokenMetadata), the on-chain identity of the
// metadata used to mint a voucher.
func MetadataImage(meta TokenMetadata) [32]byte {
	bz, err := EncodeTokenMetadata(meta)
	if err != nil {
		panic(err)
	}

	return keccak256.Sum256(bz)
}

// Uint256FromBytes32 converts a big-endian bytes32 value into a uint256.
func Uint256FromBytes32(bz [32]byte) *u256.Uint {
	return u256.Zero().SetBytes(bz[:])
}

// PredictCallProxyAccount derives a synthetic zkgm1 account for (path, channelId, sender).
// Fixed-width path/channelId plus a length-prefixed sender keep the preimage collision-free.
// reference: https://github.com/unionlabs/union/blob/d91c5e94354e15801bd5f82dc658eae3b79f2dad/cosmwasm/app/ucs03-zkgm/src/contract.rs#L3507-L3538
func PredictCallProxyAccount(path *u256.Uint, channelId types.ChannelId, sender []byte) string {
	if path == nil {
		path = u256.Zero()
	}
	pathBytes := Uint256ToBytes32(path)

	var channelBytes [4]byte
	binary.BigEndian.PutUint32(channelBytes[:], uint32(channelId))

	var senderLen [8]byte
	binary.BigEndian.PutUint64(senderLen[:], uint64(len(sender)))

	buf := make([]byte, 0, len(tagCallProxy)+len(pathBytes)+len(channelBytes)+len(senderLen)+len(sender))
	buf = append(buf, tagCallProxy...)
	buf = append(buf, pathBytes[:]...)
	buf = append(buf, channelBytes[:]...)
	buf = append(buf, senderLen[:]...)
	buf = append(buf, sender...)

	h := keccak256.Sum256(buf)

	return callProxyAccountPrefix + hex.EncodeToString(h[:20])
}

package zkgm

import (
	"crypto/keccak256"
	"encoding/binary"

	u256 "gno.land/p/onbloc/math/uint256"
)

func DeriveBatchSalt(index *u256.Uint, salt [32]byte) [32]byte {
	var input [64]byte

	putUint256BE(input[:32], index)
	copy(input[32:], salt[:])

	return keccak256.Sum256(input[:])
}

func TintForwardSalt(salt [32]byte) [32]byte {
	var out [32]byte
	for i := range salt {
		out[i] = salt[i] | FORWARD_SALT_MAGIC[i]
	}

	return out
}

func IsForwardedPacket(salt [32]byte) bool {
	for i := range salt {
		if salt[i]&FORWARD_SALT_MAGIC[i] != FORWARD_SALT_MAGIC[i] {
			return false
		}
	}

	return true
}

func DeriveForwardSalt(salt [32]byte) [32]byte {
	hash := keccak256.Sum256(salt[:])
	return TintForwardSalt(hash)
}

// Uint256ToBytes32 returns the big-endian 32-byte encoding of x.
func Uint256ToBytes32(x *u256.Uint) [32]byte {
	var out [32]byte

	putUint256BE(out[:], x)

	return out
}

// DeriveSenderSalt computes:
//
//	keccak256((sender, salt).abi_encode())
//
// matching Union's alloy-sol-types encoding of a top-level dynamic tuple.
// Callers must pass the raw UTF-8 bytes of the bech32 account string.
func DeriveSenderSalt(sender []byte, salt [32]byte) [32]byte {
	// ABI layout for alloy `(bytes, bytes32).abi_encode()`:
	//
	//   word 0: offset to top-level tuple body (0x20)
	//   word 1: offset to sender data within tuple body (0x40)
	//   word 2: salt
	//   word 3: len(sender)
	//   word 4+: sender bytes, right-padded to a 32-byte boundary
	//
	// The inner offset is relative to the start of the tuple body.
	pad := (32 - len(sender)%32) % 32
	buf := make([]byte, 4*32+len(sender)+pad)
	buf[31] = 0x20
	buf[63] = 0x40
	copy(buf[64:96], salt[:])
	binary.BigEndian.PutUint64(buf[120:128], uint64(len(sender)))
	copy(buf[128:], sender)

	return keccak256.Sum256(buf)
}

// NOTE: depends on gnoswap/uint256's internal [4]uint64 layout (mirror of
// SetBytes32). Replace with the upstream Bytes32() method once it exists.
func putUint256BE(dst []byte, x *u256.Uint) {
	binary.BigEndian.PutUint64(dst[0:8], x[3])
	binary.BigEndian.PutUint64(dst[8:16], x[2])
	binary.BigEndian.PutUint64(dst[16:24], x[1])
	binary.BigEndian.PutUint64(dst[24:32], x[0])
}

package zkgm

import (
	"errors"
	"math"

	u256 "gno.land/p/onbloc/math/uint256"
)

// ErrAmountOverflow is returned when a (downscaled) amount does not fit int64,
// the width of the grc20/banker ledger.
var ErrAmountOverflow = errors.New("zkgm: amount overflows int64")

// ErrAmountNotDivisible is returned when a source-precision amount carries precision
// below the ledger's canonical scale,
// so dividing by the token's scale factor leaves a remainder.
// It is rejected so cross-chain value is conserved exactly.
var ErrAmountNotDivisible = errors.New("zkgm: amount not divisible by token scale factor")

// ErrPow10Overflow is returned when 10^exp does not fit in a uint256.
var ErrPow10Overflow = errors.New("zkgm: 10^exp overflows uint256")

// Pow10 returns 10^exp as a uint256, rejecting exp too large to fit (>= 78)
// instead of wrapping mod 2^256.
func Pow10(exp int) (*u256.Uint, error) {
	if exp < 0 {
		return u256.Zero(), nil
	}

	result := u256.NewUint(1)
	ten := u256.NewUint(10)

	for i := 0; i < exp; i++ {
		next, overflow := new(u256.Uint).MulOverflow(result, ten)
		if overflow {
			return nil, ErrPow10Overflow
		}

		result = next
	}

	return result, nil
}

// ScaleDownToInt64 narrows an origin-precision amount to an int64 ledger amount
// by dividing by 10^scaleExp.
// scaleExp <= 0 is the identity narrow, used by native and low-decimal tokens.
func ScaleDownToInt64(amount *u256.Uint, scaleExp int) (int64, error) {
	value := amount

	if scaleExp > 0 {
		divisor, err := Pow10(scaleExp)
		if err != nil {
			return 0, err
		}

		quotient, remainder := u256.Zero().DivMod(amount, divisor, u256.Zero())
		if !remainder.IsZero() {
			return 0, ErrAmountNotDivisible
		}

		value = quotient
	}

	valueUint64, overflow := value.Uint64WithOverflow()
	if overflow || valueUint64 > uint64(math.MaxInt64) {
		return 0, ErrAmountOverflow
	}

	return int64(valueUint64), nil
}

package zkgm

import u256 "gno.land/p/onbloc/math/uint256"

// BURN_ADDRESS is the canonical zero burn address: bech32 of 20 zero bytes with
// the gno `g` HRP, matching union's get_burn_address = addr_humanize([0;20]).
// A market-maker ack naming this address burns the escrow instead of releasing it.
//
// reference: https://github.com/unionlabs/union/blob/d91c5e94354e15801bd5f82dc658eae3b79f2dad/cosmwasm/app/ucs03-zkgm/src/contract.rs#L3211
const BURN_ADDRESS = "g1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqluuxe"

// ZkgmPacket is the outer ZKGM packet envelope.
//
// Mirrors `ZkgmPacket` at com.rs:33.
type ZkgmPacket struct {
	Salt        [32]byte
	Path        *u256.Uint
	Instruction Instruction
}

// Instruction identifies an operation and carries its ABI-encoded operand.
//
// Mirrors `Instruction` at com.rs:40.
type Instruction struct {
	Version uint8
	Opcode  uint8
	Operand []byte
}

// Forward wraps another instruction for forwarding across a channel path.
//
// Mirrors `Forward` at com.rs:46.
type Forward struct {
	Path             *u256.Uint
	TimeoutHeight    uint64
	TimeoutTimestamp uint64
	Instruction      Instruction
}

// Call describes an application call instruction.
//
// Mirrors `Call` at com.rs:54.
type Call struct {
	Sender           []byte
	Eureka           bool
	ContractAddress  []byte
	ContractCalldata []byte
}

// Batch groups multiple instructions.
//
// Mirrors `Batch` at com.rs:61.
type Batch struct {
	Instructions []Instruction
}

// TokenOrderV1 is the legacy token order shape with token metadata fields.
//
// Mirrors `TokenOrderV1` at com.rs:66.
type TokenOrderV1 struct {
	Sender            []byte
	Receiver          []byte
	BaseToken         []byte
	BaseAmount        *u256.Uint
	BaseTokenSymbol   string
	BaseTokenName     string
	BaseTokenDecimals uint8
	BaseTokenPath     *u256.Uint
	QuoteToken        []byte
	QuoteAmount       *u256.Uint
}

// TokenOrderV2 is the current token order shape.
//
// Mirrors `TokenOrderV2` at com.rs:80.
type TokenOrderV2 struct {
	Sender      []byte
	Receiver    []byte
	BaseToken   []byte
	BaseAmount  *u256.Uint
	QuoteToken  []byte
	QuoteAmount *u256.Uint
	Kind        uint8
	Metadata    []byte
}

// TokenMetadata carries wrapped token implementation initialization data.
//
// Mirrors `TokenMetadata` at com.rs:92.
type TokenMetadata struct {
	Implementation []byte
	Initializer    []byte
}

// TokenInitializer holds token display metadata; decimals are metadata only, never used for scaling.
// Authority and Minter are the ZkgmERC20 initialize(...) EVM addresses (20 bytes each): the admin
// authority, and the address granted the minter role (the EVM ZKGM contract, named `zkgm` in the
// Solidity signature — see docs/guides/zkgm-packet-send/initialize.md). Leave them nil to encode
// the zero address, the default for callers that don't care about a real EVM authority/minter.
type TokenInitializer struct {
	Authority []byte
	Minter    []byte
	Name      string
	Symbol    string
	Decimals  uint8
}

// SolverMetadata carries market maker solver data.
//
// Mirrors `SolverMetadata` at com.rs:98.
type SolverMetadata struct {
	SolverAddress []byte
	Metadata      []byte
}

// Ack wraps an acknowledgement tag and payload.
//
// Mirrors `Ack` at com.rs:104.
type Ack struct {
	Tag      *u256.Uint
	InnerAck []byte
}

// BatchAck groups acknowledgement payloads.
//
// Mirrors `BatchAck` at com.rs:109.
type BatchAck struct {
	Acknowledgements [][]byte
}

// TokenOrderAck describes token order settlement acknowledgement data.
//
// Mirrors `TokenOrderAck` at com.rs:114.
type TokenOrderAck struct {
	FillType    *u256.Uint
	MarketMaker []byte
}

package access

import "gno.land/p/onbloc/access/manager"

var accessState manager.State

// RelayerRole mirrors Union deployer's RELAYER role id.
// Reference:
// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/deployer/src/main.rs#L65
const RelayerRole manager.RoleId = 1

// GrantRole grants role membership to account through the shared access realm.
// Union reference:
// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/access-manager/src/contract.rs#L69-L87
func GrantRole(cur realm, role manager.RoleId, account address) bool {
	assertCanAdminRole(0, cur, role)

	newMember := accessState.GrantRole(role, account)
	since := accessState.GetRoleMemberSince(role, account)

	emitRoleGrantedEvent(role, account, since, newMember)

	return newMember
}

// RevokeRole revokes role membership from account through the shared access realm.
// Union reference:
// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/access-manager/src/contract.rs#L89-L100
func RevokeRole(cur realm, role manager.RoleId, account address) bool {
	assertCanAdminRole(0, cur, role)

	revoked := accessState.RevokeRole(role, account)
	if revoked {
		emitRoleRevokedEvent(role, account)
	}

	return revoked
}

// RenounceRole revokes the caller's own role membership after confirmation.
// Union reference:
// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/access-manager/src/contract.rs#L102-L115
func RenounceRole(cur realm, role manager.RoleId, callerConfirmation address) bool {
	account := cur.Previous().Address()

	revoked := accessState.RenounceRole(role, account, callerConfirmation)
	if revoked {
		emitRoleRevokedEvent(role, account)
	}

	return revoked
}

// LabelRole emits role label metadata for an unlocked role.
// Union reference:
// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/access-manager/src/contract.rs#L48-L67
func LabelRole(cur realm, role manager.RoleId, label string) {
	assertCanManageTarget(0, cur)

	manager.RequireUnlockedConfigRole(role)

	emitRoleLabelEvent(role, label)
}

// SetRoleAdmin sets the admin role that can grant or revoke role.
// Union reference:
// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/access-manager/src/contract.rs#L117-L126
func SetRoleAdmin(cur realm, role manager.RoleId, admin manager.RoleId) {
	assertCanManageTarget(0, cur)

	accessState.SetRoleAdmin(role, admin)

	emitRoleAdminChangedEvent(role, admin)
}

// SetGrantDelay schedules delay behind a setback (manager.State.SetGrantDelay).
// Union reference:
// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/access-manager/src/contract.rs#L139-L148
func SetGrantDelay(cur realm, role manager.RoleId, newDelay uint32) {
	assertCanManageTarget(0, cur)

	accessState.SetGrantDelay(role, newDelay)
	effect := accessState.GetRoleGrantDelayEffect(role)

	emitRoleGrantDelayChangedEvent(role, newDelay, effect)
}

// SetFunctionRole sets the role for selector on targetPath.
// Union reference:
// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/access-manager/src/contract.rs#L353-L367
func SetFunctionRole(cur realm, targetPath string, selector manager.Selector, role manager.RoleId) {
	assertCanManageTarget(0, cur)

	accessState.SetTargetFunctionRole(targetPath, selector, role)

	emitTargetFunctionRoleUpdatedEvent(targetPath, selector, role)
}

// SetFunctionRoles sets the same role for selectors on targetPath.
// Union reference:
// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/access-manager/src/contract.rs#L353-L367
func SetFunctionRoles(cur realm, targetPath string, selectors []manager.Selector, role manager.RoleId) {
	assertCanManageTarget(0, cur)

	accessState.SetTargetFunctionRoles(targetPath, selectors, role)

	for i := range selectors {
		emitTargetFunctionRoleUpdatedEvent(targetPath, selectors[i], role)
	}
}

// SetTargetClosed sets whether targetPath is closed.
// Union reference:
// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/access-manager/src/contract.rs#L450-L483
func SetTargetClosed(cur realm, targetPath string, closed bool) {
	assertCanManageTarget(0, cur)

	accessState.SetTargetClosed(targetPath, closed)

	emitTargetClosedEvent(targetPath, closed)
}

package access

import "gno.land/p/onbloc/access/manager"

func assertIsRlmCurrent(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic(ErrSpoofedRealm)
	}
}

// AssertCanCall panics unless caller can call selector on the calling realm's target path.
// Union reference:
// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/access-managed/src/restricted.rs#L38-L66
func AssertCanCall(_ int, rlm realm, selector manager.Selector) {
	assertIsRlmCurrent(0, rlm)

	caller := rlm.Previous().Address()
	target := rlm.PkgPath()
	if !accessState.IsAuthorized(caller, target, selector) {
		panic(AccessManagerUnauthorizedCallError(caller, target, selector))
	}
}

func assertCanManageTarget(_ int, rlm realm) {
	caller := rlm.Previous().Address()
	if !accessState.CanManageTarget(caller).Immediate {
		panic(AccessManagerUnauthorizedAccountError(caller, manager.AdminRole))
	}
}

func assertCanAdminRole(_ int, rlm realm, role manager.RoleId) {
	caller := rlm.Previous().Address()
	if !accessState.CanAdminRole(role, caller).Immediate {
		panic(AccessManagerUnauthorizedAccountError(caller, accessState.GetRoleAdmin(role)))
	}
}

package access

import (
	"gno.land/p/onbloc/access/manager"
	"gno.land/p/onbloc/ibc/union/types"
)

const (
	CoreRealmPath       = "gno.land/r/onbloc/ibc/union/core"
	DefaultAdminAddress = address("g18839tls6c4w9kkxtzthjst4qdcm4lgyntvtqvs")
)

func init() {
	resetAccess(DefaultAdminAddress)
}

// resetAccess mirrors the deploy-time setup that Union performs through its
// deployer after instantiating AccessManager. Gno has no instantiate message, so
// this realm uses DefaultAdminAddress as its initial admin during init.
func resetAccess(initialAdmin address) {
	accessState = manager.NewState()

	// Mirrors initial admin bootstrap only:
	// OZ AccessManager constructor:
	// https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v5.6.1/contracts/access/manager/AccessManager.sol#L133-L136
	// Union access-manager init:
	// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/access-manager/src/lib.rs#L148-L154
	//
	// RELAYER membership is separate deployer policy in Union and is granted by
	// GrantRole, not by AccessManager initialization:
	// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/deployer/src/main.rs#L1143-L1152
	accessState.GrantRole(manager.AdminRole, initialAdmin)
	since := accessState.GetRoleMemberSince(manager.AdminRole, initialAdmin)
	emitRoleGrantedEvent(manager.AdminRole, initialAdmin, since, true)
	setupRoles()
}

// Union reference:
// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/deployer/src/main.rs#L1779
func setupRoles() {
	accessState.SetTargetFunctionRoles(CoreRealmPath, types.RelayerSelectors(), RelayerRole)
	for _, selector := range types.RelayerSelectors() {
		emitTargetFunctionRoleUpdatedEvent(CoreRealmPath, selector, RelayerRole)
	}
	// Union deployer labels all production roles. We only bootstrap RELAYER for
	// now; PAUSER/UNPAUSER/RATE_LIMITER are added when their roles are adopted.
	// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/deployer/src/main.rs#L1871-L1908
	manager.RequireUnlockedConfigRole(RelayerRole)
	emitRoleLabelEvent(RelayerRole, "RELAYER")
}

