package cometbls

import (
	"time"

	aibtypes "gno.land/p/onbloc/deps/ibc/types"
	"gno.land/p/onbloc/deps/ics23"
	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/onbloc/ibc/union/lightclient"
	"gno.land/p/onbloc/ibc/union/types"
)

// CometblsLightClient is the stateful object implementing lightclient.Interface.
//
// It holds the client state and the consensus states keyed by height, mirroring
// the host store's per-client entry as a self-contained pure object. The core
// host routes by clientId to the stored light-client object; this object owns its
// own state and is verified directly against lightclient.Interface.
type CometblsLightClient struct {
	clientState            *ClientState
	consensusStateByHeight *bptree.BPTree // height:*ConsensusState
}

var _ lightclient.Interface = (*CometblsLightClient)(nil)

// NewCometblsLightClient builds the Gno object-form light client from decoded
// client and consensus state. Core ClientImpl adapters decode MsgCreateClient
// bytes before calling this constructor.
func NewCometblsLightClient(clientState *ClientState, consensusState *ConsensusState) (*CometblsLightClient, error) {
	client := &CometblsLightClient{
		clientState:            clientState,
		consensusStateByHeight: bptree.NewBPTree32(),
	}
	client.setConsensusState(clientState.LatestHeight, consensusState)
	return client, nil
}

// Union reference:
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/cometbls/src/client.rs#L48-L72
func (c *CometblsLightClient) VerifyMembership(height uint64, key []byte, proof []byte, value []byte) error {
	clientState := c.clientState

	consensusState, storageProof, merklePath, err := c.prepareProof(clientState, height, key, proof)
	if err != nil {
		return err
	}

	return c.verifyChainedMembershipProof(consensusState.GetRoot().Hash, storageProof, merklePath, value, 0)
}

// Union reference:
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/cometbls/src/client.rs#L75-L99
func (c *CometblsLightClient) VerifyNonMembership(height uint64, key []byte, proof []byte) error {
	clientState := c.clientState

	consensusState, storageProof, merklePath, err := c.prepareProof(clientState, height, key, proof)
	if err != nil {
		return err
	}

	// VerifyNonMembership verifies the absence of the key in the lowest subtree
	// and then chains inclusion proofs of all subroots up to the final root.
	nonexist := storageProof[0].GetNonexist()
	if nonexist == nil {
		return errorWithDetails(ErrInvalidProof, "commitment proof must be non-existence proof for verifying non-membership")
	}

	subroot, err := nonexist.Calculate()
	if err != nil {
		return errorWithDetails(ErrInvalidProof, "could not calculate root for proof index 0, merkle tree is likely empty: "+err.Error())
	}

	key0 := merklePath.KeyPath[len(merklePath.KeyPath)-1]
	if err := nonexist.Verify(ics23.GetSDKProofSpecs()[0], subroot, key0); err != nil {
		return errorWithDetails(ErrInvalidProof, "failed to verify non-membership proof: "+err.Error())
	}

	// Verify the chained membership proof starting from index 1 with value =
	// subroot.
	return c.verifyChainedMembershipProof(consensusState.GetRoot().Hash, storageProof, merklePath, subroot, 1)
}

// prepareProof performs the validation shared by VerifyMembership and
// VerifyNonMembership: the proof height must not exceed the latest height, the
// proof must decode, its length must match the SDK proof specs, and a consensus
// state must exist at the height. It returns the consensus state, decoded
// storage proof and the membership path for the key.
func (c *CometblsLightClient) prepareProof(clientState *ClientState, height uint64, key []byte, proof []byte) (*ConsensusState, []ics23.CommitmentProof, aibtypes.MerklePath, error) {
	if clientState.GetLatestRevisionHeight() < height {
		return nil, nil, aibtypes.MerklePath{}, errorWithDetails(
			ErrInvalidHeight,
			ufmt.Sprintf("client state height < proof height (%d < %d), please ensure the client has been updated", clientState.GetLatestRevisionHeight(), height),
		)
	}

	storageProof, err := DecodeProofs(proof)
	if err != nil {
		return nil, nil, aibtypes.MerklePath{}, errorWithDetails(ErrInvalidProof, "failed to decode proof: "+err.Error())
	}

	specs := ics23.GetSDKProofSpecs()
	if len(storageProof) != len(specs) {
		return nil, nil, aibtypes.MerklePath{}, errorWithDetails(
			ErrInvalidProof,
			ufmt.Sprintf("length of specs: %d not equal to length of proof: %d", len(specs), len(storageProof)),
		)
	}

	consensusState, found := c.getConsensusState(types.NewHeight(height))
	if !found {
		return nil, nil, aibtypes.MerklePath{}, errorWithDetails(ErrInvalidConsensus, "please ensure the proof was constructed against a height that exists on the client")
	}

	merklePath := aibtypes.MerklePath{KeyPath: [][]byte{moduleKey, makeStoreKey(clientState.ContractAddress, key)}}

	return consensusState, storageProof, merklePath, nil
}

// Union reference:
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/cometbls/src/client.rs#L143-L160
func (c *CometblsLightClient) VerifyHeader(caller address, headerBytes []byte, relayer address) (types.StateUpdate, error) {
	header, err := DecodeHeader(headerBytes)
	if err != nil {
		return types.StateUpdate{}, errorWithDetails(ErrInvalidHeader, "failed to decode header: "+err.Error())
	}

	consensusState, found := c.getConsensusState(*header.TrustedHeight)
	if !found {
		return types.StateUpdate{}, errorWithDetails(
			ErrInvalidConsensus,
			ufmt.Sprintf("could not get trusted consensus state for Header at TrustedHeight: %s", header.TrustedHeight),
		)
	}

	headerHeight := header.GetHeight()
	if consensusState, found := c.getConsensusState(headerHeight); found {
		return makeStateUpdate(headerHeight, consensusState), nil
	}

	if err := c.verifyHeader(c.clientState, consensusState, header, time.Now()); err != nil {
		return types.StateUpdate{}, err
	}

	return c.updateState(c.clientState, consensusState, header), nil
}

// Union reference (verify_creation is a no-op there):
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/cometbls/src/client.rs#L134-L141
func (c *CometblsLightClient) VerifyCreation(caller address, relayer address) (types.ClientCreationResult, error) {
	// Unlike Union, we validate basic invariants (ClientState.Validate), but
	// like Union we skip bounding TrustingPeriod (see Validate). Writes nothing.
	if err := c.clientState.Validate(); err != nil {
		return types.ClientCreationResult{}, err
	}

	return types.ClientCreationResult{}, nil
}

func (c *CometblsLightClient) Misbehaviour(caller address, misbehaviour []byte, relayer address) ([]byte, error) {
	m, err := DecodeMisbehaviour(misbehaviour)
	if err != nil {
		return nil, errorWithDetails(ErrInvalidMisbehaviour, "failed to decode misbehaviour: "+err.Error())
	}

	if err := m.ValidateBasic(); err != nil {
		return nil, err
	}

	if err := c.verifyMisbehaviour(m, time.Now()); err != nil {
		return nil, err
	}

	// Freeze the client. The frozen height is a sentinel boolean (non-zero).
	c.clientState.FrozenHeight = FrozenHeight

	// Return the frozen client-state bytes so the host commits them back to its
	// client-state mirror, matching union's misbehaviour handling.
	csBytes, err := EncodeClientState(c.clientState)
	if err != nil {
		return nil, err
	}

	return csBytes, nil
}

// updateState creates or updates the consensus state for a verified header and
// advances the latest height when the header is newer. It mirrors Union's
// update_state in Union's cometbls client.
// Union reference:
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/cometbls/src/client.rs#L283-L309
func (c *CometblsLightClient) updateState(clientState *ClientState, trustedConsensusState *ConsensusState, header *Header) types.StateUpdate {
	untrustedHeight := header.GetHeight()

	consensusState := &ConsensusState{
		Timestamp:          trustedConsensusState.Timestamp,
		Root:               trustedConsensusState.Root,
		NextValidatorsHash: trustedConsensusState.NextValidatorsHash,
	}

	consensusState.Root = MerkleRoot{Hash: header.SignedHeader.AppHash}
	consensusState.NextValidatorsHash = header.SignedHeader.NextValidatorsHash
	// Normalized to nanoseconds to follow tendermint convention
	consensusState.Timestamp = uint64(header.GetTime().UnixNano())

	c.setConsensusState(untrustedHeight, consensusState)

	stateUpdate := makeStateUpdate(untrustedHeight, consensusState)
	if untrustedHeight.GT(clientState.LatestHeight) {
		clientState.LatestHeight = untrustedHeight
		if csBytes, err := EncodeClientState(clientState); err == nil {
			stateUpdate.ClientStateBytes = csBytes
		}
	}

	return stateUpdate
}

func makeStateUpdate(height types.Height, consensusState *ConsensusState) types.StateUpdate {
	update := types.StateUpdate{Height: height.RevisionHeight}
	if consBytes, err := EncodeConsensusState(consensusState); err == nil {
		update.ConsensusStateBytes = consBytes
	}

	return update
}

func (c *CometblsLightClient) GetTimestamp() types.Timestamp {
	lastConsState, found := c.getConsensusState(c.clientState.LatestHeight)
	if !found {
		return 0
	}

	return types.Timestamp(lastConsState.Timestamp)
}

func (c *CometblsLightClient) GetTimestampAtHeight(height uint64) (types.Timestamp, error) {
	consensusState, found := c.getConsensusState(types.NewHeight(height))
	if !found {
		return 0, errorWithDetails(ErrInvalidConsensus, "no consensus state at height")
	}

	return types.Timestamp(consensusState.Timestamp), nil
}

func (c *CometblsLightClient) GetLatestHeight() uint64 {
	return c.clientState.GetLatestRevisionHeight()
}

func (c *CometblsLightClient) GetCounterpartyChainID() string {
	return c.clientState.ChainID
}

func (c *CometblsLightClient) Status() lightclient.Status {
	if !c.clientState.FrozenHeight.IsZero() {
		return lightclient.Frozen
	}

	// get latest consensus state to check for expiry
	lastConsState, found := c.getConsensusState(c.clientState.LatestHeight)
	if !found {
		// if the client state does not have an associated consensus state for its
		// latest height then it must be expired
		return lightclient.Expired
	}

	if c.clientState.IsExpired(lastConsState.Timestamp, uint64(time.Now().UnixNano())) {
		return lightclient.Expired
	}

	return lightclient.Active
}

func (c *CometblsLightClient) hasConsensusState(height types.Height) bool {
	return c.consensusStateByHeight.Has(heightKey(height))
}

func (c *CometblsLightClient) getConsensusState(height types.Height) (*ConsensusState, bool) {
	v := c.consensusStateByHeight.Get(heightKey(height))
	if v == nil {
		return nil, false
	}

	consensusState, ok := v.(*ConsensusState)
	if !ok {
		return nil, false
	}

	return consensusState, true
}

func (c *CometblsLightClient) setConsensusState(height types.Height, consensusState *ConsensusState) {
	c.consensusStateByHeight.Set(heightKey(height), consensusState)
}

package cometbls

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/onbloc/ibc/union/types"
)

// https://github.com/cometbft/cometbft/blob/6b567cd510acb6d729869db8621ae93ac79247cf/types/genesis.go#L18-L21
const MaxChainIDLen int = 50

// Union reference (no UnbondingPeriod field):
// https://github.com/unionlabs/union/blob/0ceb6f830211d752b7c099e4630e2c95d3c179d1/lib/cometbls-light-client-types/src/client_state.rs#L13-L31
type ClientState struct {
	ChainID         string
	TrustingPeriod  uint64
	MaxClockDrift   uint64
	FrozenHeight    types.Height
	LatestHeight    types.Height
	ContractAddress types.H256
}

func NewClientState(
	chainID string,
	trustingPeriod uint64,
	maxClockDrift uint64,
	frozenHeight types.Height,
	latestHeight types.Height,
	contractAddress types.H256,
) *ClientState {
	return &ClientState{
		ChainID:         chainID,
		TrustingPeriod:  trustingPeriod,
		MaxClockDrift:   maxClockDrift,
		FrozenHeight:    frozenHeight,
		LatestHeight:    latestHeight,
		ContractAddress: contractAddress,
	}
}

// ClientType is tendermint.
func (ClientState) ClientType() string {
	return ClientType
}

// GetChainID returns the chain-id
func (cs *ClientState) GetChainID() string {
	return cs.ChainID
}

func (cs *ClientState) GetTrustingPeriod() uint64 {
	return cs.TrustingPeriod
}

func (cs *ClientState) GetMaxClockDrift() uint64 {
	return cs.MaxClockDrift
}

// GetLatestHeight returns latest block height.
func (cs *ClientState) GetLatestHeight() types.Height {
	return cs.LatestHeight
}

func (cs *ClientState) GetFrozenRevisionHeight() uint64 {
	return cs.FrozenHeight.RevisionHeight
}

// GetLatestRevisionHeight returns latest block height.
func (cs *ClientState) GetLatestRevisionHeight() uint64 {
	return cs.LatestHeight.RevisionHeight
}

func (cs *ClientState) GetContractAddress() types.H256 {
	return cs.ContractAddress
}

// IsExpired returns whether or not the client has passed the trusting period since the last
// update (in which case no headers are considered valid).
func (cs *ClientState) IsExpired(latestTimestamp, now uint64) bool {
	return isClientExpiredAt(latestTimestamp, cs.TrustingPeriod, now)
}

// Validate performs a basic validation of the client state fields.
func (cs *ClientState) Validate() error {
	if strings.TrimSpace(cs.ChainID) == "" {
		return errorWithDetails(ErrInvalidChainID, "chain id cannot be empty string")
	}

	// NOTE: the value of tmtypes.MaxChainIDLen may change in the future.
	// If this occurs, the code here must account for potential difference
	// between the tendermint version being run by the counterparty chain
	// and the tendermint version used by this light client.
	// https://github.com/cosmos/ibc-go/issues/177
	if len(cs.ChainID) > MaxChainIDLen {
		return errorWithDetails(
			ErrInvalidChainID,
			ufmt.Sprintf("chainID is too long; got: %d, max: %d", len(cs.ChainID), MaxChainIDLen),
		)
	}

	if cs.TrustingPeriod <= 0 {
		return errorWithDetails(ErrInvalidTrustingPeriod, "trusting period must be greater than zero")
	}

	// No upper bound on TrustingPeriod: Union doesn't check it either (see
	// VerifyCreation), relying on gating CreateClient to the relayer role.
	// https://github.com/unionlabs/union/blob/8cff0ff34f6baa4cdb1e4650a08985dd05de0c5a/cosmwasm/deployer/src/main.rs#L1786-L1830

	if cs.MaxClockDrift <= 0 {
		return errorWithDetails(ErrInvalidMaxClockDrift, "max clock drift must be greater than zero")
	}

	if cs.GetLatestRevisionHeight() == 0 {
		return errorWithDetails(ErrInvalidHeaderHeight, "cometbls client's latest height cannot be zero")
	}

	return nil
}

// ZeroCustomFields returns a ClientState that is a copy of the current ClientState
// with all client customizable fields zeroed out
func (cs *ClientState) ZeroCustomFields() *ClientState {
	// copy over all chain-specified fields
	// and leave custom fields empty
	return &ClientState{
		ChainID:      cs.ChainID,
		LatestHeight: cs.LatestHeight,
	}
}

package cometbls

import (
	"bytes"
	"crypto/cometblszk"
	"encoding/hex"
	"time"

	aibtypes "gno.land/p/onbloc/deps/ibc/types"
	"gno.land/p/onbloc/deps/ics23"
	"gno.land/p/nt/ufmt/v0"
)

// verifyHeader verifies a CometBLS Header against the client's state and the
// trusted ConsensusState at header.TrustedHeight. It mirrors Union's
// cometbls verify_header in client.rs, preserving the order of checks and their
// error semantics:
//   - the trusted consensus state must exist for header.TrustedHeight
//   - header revision must match the trusted height revision
//   - the trusted timestamp must be strictly less than the header timestamp
//   - header height must be greater than the trusted height
//   - header time must be within the max clock drift of the current block time
//   - for an adjacent block, the header validators hash must match the trusted
//     next validators hash
//   - the Groth16 proof must verify against the trusted next validators hash
//
// now is the current block time, used for the clock-drift bound.
// Union reference:
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/cometbls/src/client.rs#L185-L254
func (c *CometblsLightClient) verifyHeader(clientState *ClientState, trustedConsensusState *ConsensusState, header *Header, now time.Time) error {
	// The untrusted (signed) header height. CometBLS carries a single revision,
	// so heights are compared against the trusted height's revision height.
	untrustedHeightNumber := header.SignedHeader.Height
	trustedHeightNumber := header.TrustedHeight.RevisionHeight

	if untrustedHeightNumber <= int64(trustedHeightNumber) {
		return errorWithDetails(
			ErrInvalidHeader,
			ufmt.Sprintf("header height <= consensus state height (%d <= %d)", untrustedHeightNumber, trustedHeightNumber),
		)
	}

	trustedTimestamp := trustedConsensusState.GetTimestamp()
	// Normalize to nanoseconds to follow tendermint convention
	untrustedTimestamp := uint64(header.GetTime().UnixNano())

	if untrustedTimestamp <= trustedTimestamp {
		return errorWithDetails(
			ErrInvalidHeaderTimestamp,
			ufmt.Sprintf(
				"trusted header timestamp %d is greater than or equal to the new header timestamp %d",
				trustedTimestamp, untrustedTimestamp,
			),
		)
	}

	currentBlockTime := uint64(now.UnixNano())
	if isClientExpiredAt(trustedTimestamp, clientState.TrustingPeriod, currentBlockTime) {
		return errorWithDetails(
			ErrTrustingPeriodExpired,
			ufmt.Sprintf("trusted consensus state at TrustedHeight %s has expired", header.TrustedHeight),
		)
	}

	maxClockDriftTimestamp, overflow := checkedAddUint64(currentBlockTime, clientState.MaxClockDrift)
	if overflow {
		return errorWithDetails(ErrMathOverflow)
	}

	if untrustedTimestamp >= maxClockDriftTimestamp {
		return errorWithDetails(
			ErrInvalidHeader,
			ufmt.Sprintf("header time >= max drift (%d >= currentTime + %d)", untrustedTimestamp, clientState.MaxClockDrift),
		)
	}

	trustedValidatorsHash := trustedConsensusState.GetNextValidatorsHash()
	// For an adjacent block, the header validators hash must match the trusted
	// next validators hash.
	if untrustedHeightNumber == int64(trustedHeightNumber)+1 &&
		!bytes.Equal(header.SignedHeader.ValidatorsHash, trustedValidatorsHash) {
		return errorWithDetails(
			ErrInvalidHeader,
			ufmt.Sprintf(
				"the validators hash %s doesn't match the trusted validators hash %s for an adjacent block",
				hex.EncodeToString(header.SignedHeader.ValidatorsHash), hex.EncodeToString(trustedValidatorsHash),
			),
		)
	}

	// The trusted next validators hash commits to the validator set that signed
	// the untrusted header; the Groth16 proof attests that they did. SignedHeader
	// is a crypto/cometblszk.LightHeader, so it feeds VerifyZKP directly.
	if err := cometblszk.VerifyZKP(
		clientState.ChainID,
		trustedValidatorsHash,
		*header.SignedHeader,
		header.ZeroKnowledgeProof,
	); err != nil {
		return errorWithDetails(ErrInvalidHeader, "zero-knowledge proof verification failed: "+err.Error())
	}

	return nil
}

func isClientExpiredAt(consensusStateTimestamp uint64, trustingPeriod uint64, now uint64) bool {
	expiresAt, overflow := checkedAddUint64(consensusStateTimestamp, trustingPeriod)
	if overflow {
		return true
	}

	return expiresAt < now
}

func checkedAddUint64(a uint64, b uint64) (uint64, bool) {
	sum := a + b
	if sum < a {
		return 0, true
	}

	return sum, false
}

// verifyMisbehaviour verifies both headers and checks for same-height conflict
// or non-increasing time across heights.
// Union reference:
// https://github.com/unionlabs/union/blob/3b1e861e9724601c458af278a30420cb11a72314/evm/contracts/clients/CometblsClient.sol#L280-L316
func (c *CometblsLightClient) verifyMisbehaviour(misbehaviour *Misbehaviour, now time.Time) error {
	headerA := misbehaviour.Header1
	headerB := misbehaviour.Header2

	if headerA.SignedHeader.Height < headerB.SignedHeader.Height {
		return errorWithDetails(ErrInvalidMisbehaviourHeaderSequence)
	}

	// Regardless of the type of misbehaviour, ensure that both headers are valid
	// and would have been accepted by the light client.
	if err := c.verifyMisbehaviourHeader("Header_1", headerA, now); err != nil {
		return err
	}

	if err := c.verifyMisbehaviourHeader("Header_2", headerB, now); err != nil {
		return err
	}

	if !isMisbehaviourPair(headerA, headerB) {
		return errorWithDetails(ErrMisbehaviourNotFound)
	}

	return nil
}

// isMisbehaviourPair reports whether two independently-valid headers constitute
// accepted misbehaviour: at the same height the signed headers must differ
// (equivocation); at different heights the earlier-listed header must not be
// strictly newer than the later one.
func isMisbehaviourPair(headerA, headerB *Header) bool {
	if headerA.SignedHeader.Height == headerB.SignedHeader.Height {
		return !signedHeadersEqual(headerA.SignedHeader, headerB.SignedHeader)
	}

	return headerA.GetTime().UnixNano() <= headerB.GetTime().UnixNano()
}

func (c *CometblsLightClient) verifyMisbehaviourHeader(label string, header *Header, now time.Time) error {
	prefix := ufmt.Sprintf("verifying %s in Misbehaviour failed: ", label)

	consensusState, found := c.getConsensusState(*header.TrustedHeight)
	if !found {
		return errorWithDetails(
			ErrInvalidMisbehaviour,
			prefix+ufmt.Sprintf("could not get trusted consensus state for Header at TrustedHeight: %s", header.TrustedHeight),
		)
	}

	if err := c.verifyHeader(c.clientState, consensusState, header, now); err != nil {
		return errorWithDetails(ErrInvalidMisbehaviour, prefix+err.Error())
	}

	return nil
}

// signedHeadersEqual reports whether two light headers have identical content.
func signedHeadersEqual(a, b *LightHeader) bool {
	if a == nil || b == nil {
		return a == b
	}

	if a.Height != b.Height || a.TimeSeconds != b.TimeSeconds || a.TimeNanos != b.TimeNanos {
		return false
	}

	return bytes.Equal(a.ValidatorsHash, b.ValidatorsHash) &&
		bytes.Equal(a.NextValidatorsHash, b.NextValidatorsHash) &&
		bytes.Equal(a.AppHash, b.AppHash)
}

// verifyChainedMembershipProof verifies a chain of ICS23 membership proofs.
// Proofs/specs are ordered from the lowest subtree to the root, while keys
// are ordered from the root to the lowest subtree.
//
// Starting at index, each proof must commit to the subroot produced by the
// previous proof (or the initial value). The final derived root must match
// the expected root.
//
// index allows verification to begin after a non-membership proof, using the
// previously computed subroot as the initial value.
func (c *CometblsLightClient) verifyChainedMembershipProof(
	root []byte,
	proofs []ics23.CommitmentProof,
	keys aibtypes.MerklePath,
	value []byte,
	index int,
) error {
	subroot := value
	specs := ics23.GetSDKProofSpecs()

	var err error

	// Start with the provided value. If no proofs remain, subroot is compared
	// directly against the expected root.
	for i := index; i < len(proofs); i++ {
		key := keys.KeyPath[len(keys.KeyPath)-1-i]

		// verify membership of the proof at this index with appropriate key and value
		subroot, err = c.verifyMembershipProofAt(proofs[i], specs[i], key, value, i)
		if err != nil {
			return err
		}

		// Use the computed subroot as the value for the next proof.
		value = subroot
	}

	// Ensure the final chained root matches the expected root.
	if !bytes.Equal(root, subroot) {
		h1, h2 := hex.EncodeToString(root), hex.EncodeToString(subroot)

		return errorWithDetails(
			ErrInvalidProof,
			ufmt.Sprintf("proof did not commit to expected root: %s, got: %s. Please ensure proof was submitted with correct proofHeight and to the correct chain.", h1, h2),
		)
	}

	return nil
}

// verifyMembershipProofAt verifies the existence proof at a single chain index
// and returns its calculated subroot. index is used only for error context.
func (c *CometblsLightClient) verifyMembershipProofAt(proof ics23.CommitmentProof, spec *ics23.ProofSpec, key, value []byte, index int) ([]byte, error) {
	exist := proof.GetExist()
	if exist == nil {
		return nil, errorWithDetails(
			ErrInvalidProof,
			"commitment proof must be existence proof foar verifying membership",
		)
	}

	subroot, err := exist.Calculate()
	if err != nil {
		return nil, errorWithDetails(
			ErrInvalidProof,
			ufmt.Sprintf("could not calculate proof root at index %d, merkle tree may be empty. %v", index, err),
		)
	}

	if err := exist.Verify(spec, subroot, key, value); err != nil {
		return nil, errorWithDetails(
			ErrInvalidProof,
			ufmt.Sprintf("failed to verify membership proof at index %d: %v", index, err),
		)
	}

	return subroot, nil
}

package cometbls

import (
	abienc "gno.land/p/onbloc/encoding/abi"
	"gno.land/p/onbloc/ibc/union/types"
)

// Wire formats for the cometbls client and consensus state.
//
// ibc-union heights carry a single revision (revision 0), so only the revision
// height is encoded; decoding rebuilds the Height with types.NewHeight.

var clientStateSchema = abienc.Schema{Fields: []abienc.Field{
	{Type: abienc.TypeBytes32},
	{Type: abienc.TypeUint64},
	{Type: abienc.TypeUint64},
	{Type: abienc.TypeUint64},
	{Type: abienc.TypeUint64},
	{Type: abienc.TypeBytes32},
}}

var consensusStateSchema = abienc.Schema{Fields: []abienc.Field{
	{Type: abienc.TypeUint64},  // Timestamp
	{Type: abienc.TypeBytes32}, // Root (app hash)
	{Type: abienc.TypeBytes32}, // NextValidatorsHash
}}

func EncodeClientState(m *ClientState) ([]byte, error) {
	var chainIdWord [32]byte

	chainBytes := []byte(m.ChainID)
	if len(chainBytes) > 31 {
		chainBytes = chainBytes[:31]
	}

	copy(chainIdWord[:], chainBytes)

	return abienc.Encode(clientStateSchema, []any{
		chainIdWord,
		m.TrustingPeriod,
		m.MaxClockDrift,
		uint64(m.FrozenHeight.RevisionHeight),
		uint64(m.LatestHeight.RevisionHeight),
		[32]byte(m.ContractAddress),
	})
}

func DecodeClientState(buf []byte) (*ClientState, error) {
	vals, err := abienc.Decode(clientStateSchema, buf)
	if err != nil {
		return nil, err
	}

	chainIdWord := vals[0].([32]byte)
	chainID := trimNullBytes(chainIdWord)
	trustingPeriod := vals[1].(uint64)
	maxClockDrift := vals[2].(uint64)
	frozenHeight := types.NewHeight(vals[3].(uint64))
	latestHeight := types.NewHeight(vals[4].(uint64))
	contractAddress := vals[5].([32]byte)

	return NewClientState(
		chainID,
		trustingPeriod,
		maxClockDrift,
		frozenHeight,
		latestHeight,
		contractAddress,
	), nil
}

// EncodeConsensusState ABI-encodes a ConsensusState (96 bytes).
// Root.Hash must be exactly 32 bytes.
func EncodeConsensusState(cs *ConsensusState) ([]byte, error) {
	appHash, err := toBytes32(cs.Root.Hash)
	if err != nil {
		return nil, err
	}

	validatorsHash, err := toBytes32(cs.NextValidatorsHash)
	if err != nil {
		return nil, err
	}

	return abienc.Encode(
		consensusStateSchema,
		[]any{cs.Timestamp, appHash, validatorsHash},
	)
}

func DecodeConsensusState(buf []byte) (*ConsensusState, error) {
	vals, err := abienc.Decode(consensusStateSchema, buf)
	if err != nil {
		return nil, err
	}

	var cs ConsensusState

	rootHash, ok := vals[1].([32]byte)
	if !ok {
		return nil, ErrDecodeState
	}

	nextValidatorsHash, ok := vals[2].([32]byte)
	if !ok {
		return nil, ErrDecodeState
	}

	cs.Timestamp = vals[0].(uint64)
	cs.Root.Hash = rootHash[:]
	cs.NextValidatorsHash = nextValidatorsHash[:]

	return &cs, nil
}

func trimNullBytes(b [32]byte) string {
	end := 32
	for end > 0 && b[end-1] == 0 {
		end--
	}

	return string(b[:end])
}

package cometbls

type ConsensusState struct {
	Timestamp          uint64
	Root               MerkleRoot
	NextValidatorsHash []byte
}

func NewConsensusState(
	timestamp uint64,
	root MerkleRoot,
	nextValidatorsHash []byte,
) *ConsensusState {
	return &ConsensusState{
		Timestamp:          timestamp,
		Root:               root,
		NextValidatorsHash: nextValidatorsHash,
	}
}

func (ConsensusState) ClientType() string {
	return ClientType
}

func (cs *ConsensusState) GetRoot() MerkleRoot {
	return cs.Root
}

func (cs *ConsensusState) GetRootHash() []byte {
	return cs.Root.Hash
}

func (cs *ConsensusState) GetTimestamp() uint64 {
	return cs.Timestamp
}

func (cs *ConsensusState) GetNextValidatorsHash() []byte {
	return cs.NextValidatorsHash
}

func (cs *ConsensusState) ValidateBasic() error {
	if cs.Root.Hash == nil || cs.Root.Empty() {
		return errorWithDetails(ErrInvalidConsensus, "root hash cannot be nil")
	}

	if err := validateHash(cs.NextValidatorsHash); err != nil {
		return errorWithDetails(ErrInvalidNextValidatorsHash, err.Error())
	}

	return nil
}

package cometbls

import (
	"errors"

	"gno.land/p/onbloc/deps/encoding/proto"
	abienc "gno.land/p/onbloc/encoding/abi"
	"gno.land/p/onbloc/ibc/union/types"
)

// Wire formats for CometBLS client messages.
//
// Each light client owns the parsing of its own client messages, since the
// header layout differs per client. CometBLS uses:
//   - Header: Ethereum ABI tuple (mirrors Union's Solidity Header struct)
//   - Misbehaviour: protobuf with two embedded ABI-encoded headers
//
// Header ABI layout (Solidity params tuple form):
//
//	[0] uint64  Height
//	[1] uint64  TimeSeconds
//	[2] uint64  TimeNanos
//	[3] bytes32 ValidatorsHash
//	[4] bytes32 NextValidatorsHash
//	[5] bytes32 AppHash
//	[6] uint64  TrustedHeight
//	[7] bytes   ZeroKnowledgeProof (dynamic)
var headerSchema = abienc.Schema{Fields: []abienc.Field{
	{Type: abienc.TypeUint64},
	{Type: abienc.TypeUint64},
	{Type: abienc.TypeUint64},
	{Type: abienc.TypeBytes32},
	{Type: abienc.TypeBytes32},
	{Type: abienc.TypeBytes32},
	{Type: abienc.TypeUint64},
	{Type: abienc.TypeBytes},
}}

// maxTimeNanos bounds the sub-second component of a header timestamp.
const maxTimeNanos = 1_000_000_000

// EncodeHeader ABI-encodes a Header. ValidatorsHash, NextValidatorsHash and
// AppHash must each be exactly 32 bytes.
func EncodeHeader(h *Header) ([]byte, error) {
	if h == nil || h.SignedHeader == nil {
		return nil, errors.New("nil header")
	}

	lh := h.SignedHeader

	vh, err := toBytes32(lh.ValidatorsHash)
	if err != nil {
		return nil, err
	}

	nvh, err := toBytes32(lh.NextValidatorsHash)
	if err != nil {
		return nil, err
	}

	ah, err := toBytes32(lh.AppHash)
	if err != nil {
		return nil, err
	}

	var trustedHeight uint64
	if h.TrustedHeight != nil {
		trustedHeight = h.TrustedHeight.RevisionHeight
	}

	return abienc.Encode(headerSchema, []any{
		uint64(lh.Height),
		uint64(lh.TimeSeconds),
		uint64(lh.TimeNanos),
		vh, nvh, ah,
		trustedHeight,
		h.ZeroKnowledgeProof,
	})
}

// DecodeHeader ABI-decodes a Header.
func DecodeHeader(buf []byte) (*Header, error) {
	vals, err := abienc.Decode(headerSchema, buf)
	if err != nil {
		return nil, errors.New("" + err.Error())
	}

	timeSeconds := vals[1].(uint64)

	timeNanos := vals[2].(uint64)
	if timeNanos >= maxTimeNanos {
		return nil, errors.New("TimeNanos out of range")
	}

	vh := vals[3].([32]byte)
	nvh := vals[4].([32]byte)
	ah := vals[5].([32]byte)

	trustedHeight := types.NewHeight(vals[6].(uint64))

	return &Header{
		SignedHeader: &LightHeader{
			Height:             int64(vals[0].(uint64)),
			TimeSeconds:        int64(timeSeconds),
			TimeNanos:          int32(timeNanos),
			ValidatorsHash:     vh[:],
			NextValidatorsHash: nvh[:],
			AppHash:            ah[:],
		},
		TrustedHeight:      &trustedHeight,
		ZeroKnowledgeProof: vals[7].([]byte),
	}, nil
}

// EncodeMisbehaviour protobuf-encodes a Misbehaviour: field 1 is Header1 and
// field 2 is Header2, each an ABI-encoded header.
func EncodeMisbehaviour(m *Misbehaviour) ([]byte, error) {
	if m == nil {
		return nil, errors.New("nil misbehaviour")
	}

	h1, err := EncodeHeader(m.Header1)
	if err != nil {
		return nil, err
	}

	h2, err := EncodeHeader(m.Header2)
	if err != nil {
		return nil, err
	}

	buf := make([]byte, 0, len(h1)+len(h2)+8)
	buf = proto.AppendLengthDelimited(buf, 1, h1)
	buf = proto.AppendLengthDelimited(buf, 2, h2)

	return buf, nil
}

// DecodeMisbehaviour protobuf-decodes a Misbehaviour.
func DecodeMisbehaviour(buf []byte) (*Misbehaviour, error) {
	m := &Misbehaviour{}

	pos := 0
	for pos < len(buf) {
		fieldNum, wireType, newPos, err := decodeTag(buf, pos)
		if err != nil {
			return nil, err
		}

		pos = newPos

		if wireType != proto.LEN {
			pos, err = skipField(buf, pos, wireType)
			if err != nil {
				return nil, err
			}

			continue
		}

		s, newPos, err := proto.DecodeString(buf, pos)
		if err != nil {
			return nil, err
		}

		pos = newPos

		header, err := DecodeHeader([]byte(s))
		if err != nil {
			return nil, err
		}

		switch fieldNum {
		case 1:
			m.Header1 = header
		case 2:
			m.Header2 = header
		}
	}

	if m.Header1 == nil || m.Header2 == nil {
		return nil, errors.New("misbehaviour missing a header")
	}

	return m, nil
}

// toBytes32 converts a 32-byte slice into a [32]byte array, returning an error
// for any other length.
func toBytes32(b []byte) ([32]byte, error) {
	var out [32]byte
	if len(b) != 32 {
		return out, errors.New("must be 32 bytes")
	}

	copy(out[:], b)

	return out, nil
}

package cometbls

import (
	"crypto/cometblszk"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/onbloc/ibc/union/types"
)

type Header struct {
	SignedHeader       *LightHeader
	TrustedHeight      *types.Height
	ZeroKnowledgeProof []byte
}

func NewHeader(
	signedHeader *LightHeader,
	trustedHeight *types.Height,
	zeroKnowledgeProof []byte,
) *Header {
	return &Header{
		SignedHeader:       signedHeader,
		TrustedHeight:      trustedHeight,
		ZeroKnowledgeProof: zeroKnowledgeProof,
	}
}

func (Header) ClientType() string {
	return ClientType
}

func (h *Header) ConsensusState() *ConsensusState {
	return &ConsensusState{
		Timestamp:          uint64(h.GetTime().UnixNano()),
		Root:               MerkleRoot{Hash: h.SignedHeader.AppHash},
		NextValidatorsHash: h.SignedHeader.NextValidatorsHash,
	}
}

// GetHeight returns the height of the signed (untrusted) header. CometBLS
// carries a single revision, so it shares the trusted height's revision number.
func (h *Header) GetHeight() types.Height {
	return types.NewHeightWithRevision(h.TrustedHeight.RevisionNumber, uint64(h.SignedHeader.Height))
}

func (h *Header) GetTime() time.Time {
	return time.Unix(h.SignedHeader.TimeSeconds, int64(h.SignedHeader.TimeNanos)).UTC()
}

// ValidateBasic calls the SignedHeader ValidateBasic function and checks
// that validatorsets are not nil.
// NOTE: TrustedHeight and TrustedValidators may be empty when creating client
// with MsgCreateClient
func (h *Header) ValidateBasic() error {
	if h.SignedHeader == nil {
		return errorWithDetails(ErrInvalidHeader, "signed header cannot be nil")
	}

	if len(h.ZeroKnowledgeProof) == 0 {
		return errorWithDetails(ErrInvalidHeader, "zero-knowledge proof cannot be empty")
	}

	// TrustedHeight is less than Header for updates and misbehaviour
	if h.TrustedHeight.GTE(h.GetHeight()) {
		return errorWithDetails(
			ErrInvalidHeaderHeight,
			ufmt.Sprintf("TrustedHeight %d must be less than header height %d", h.TrustedHeight, h.GetHeight()),
		)
	}

	return nil
}

// LightHeader is the bespoke CometBLS light header. It is an alias of
// crypto/cometblszk.LightHeader so a SignedHeader feeds VerifyZKP directly
// without re-mapping, and its TimeSeconds/TimeNanos split mirrors the ABI wire
// format (see headerSchema in encoding.gno).
type LightHeader = cometblszk.LightHeader

func NewLightHeader(height, timeSeconds int64, timeNanos int32, validatorsHash, nextValidatorsHash, appHash []byte) *LightHeader {
	return &LightHeader{
		Height:             height,
		TimeSeconds:        timeSeconds,
		TimeNanos:          timeNanos,
		ValidatorsHash:     validatorsHash,
		NextValidatorsHash: nextValidatorsHash,
		AppHash:            appHash,
	}
}

package cometbls

import (
	"strconv"
	"strings"

	"gno.land/p/onbloc/ibc/union/types"
)

const (
	ModuleName = "cometbls"

	ClientType = ModuleName
)

var moduleKey = []byte("wasm")

func makeStoreKey(addr types.H256, key []byte) []byte {
	out := make([]byte, 0, 1+32+1+len(key))
	out = append(out, 0x03)
	out = append(out, addr[:]...)
	out = append(out, 0x00)
	out = append(out, key...)

	return out
}

// heightKey renders a height as a fixed-width, lexicographically sortable bptree
// key. CometBLS uses a single revision, so the revision-height ordering matches
// numeric ordering.
func heightKey(height types.Height) string {
	return zeroPadDecimalUint64(height.RevisionNumber) + "-" + zeroPadDecimalUint64(height.RevisionHeight)
}

// zeroPadDecimalUint64 converts a uint64 number into a zero-padded 20-character string.
//
// num (uint64): The number to encode.
//
// Returns:
// A zero-padded string representation of the number.
func zeroPadDecimalUint64(num uint64) string {
	// Convert the value to a decimal string.
	s := strconv.FormatUint(num, 10)

	// Zero-pad to a total length of 20 characters.
	zerosNeeded := 20 - len(s)

	return strings.Repeat("0", zerosNeeded) + s
}

package cometbls

import (
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/onbloc/ibc/union/types"
)

var FrozenHeight = types.NewHeightWithRevision(0, 1)

type Misbehaviour struct {
	Header1 *Header
	Header2 *Header
}

func NewMisbehaviour(header1 *Header, header2 *Header) *Misbehaviour {
	return &Misbehaviour{Header1: header1, Header2: header2}
}

func (Misbehaviour) ClientType() string {
	return ClientType
}

// GetTime returns the timestamp at which misbehaviour occurred. It uses the
// maximum value from both headers to prevent producing an invalid header outside
// of the misbehaviour age range.
func (m *Misbehaviour) GetTime() time.Time {
	t1, t2 := m.Header1.GetTime(), m.Header2.GetTime()
	if t1.After(t2) {
		return t1
	}

	return t2
}

// ValidateBasic implements Misbehaviour interface
func (m *Misbehaviour) ValidateBasic() error {
	if m.Header1 == nil {
		return errorWithDetails(ErrInvalidHeader, "misbehaviour Header_1 cannot be nil")
	}

	if m.Header2 == nil {
		return errorWithDetails(ErrInvalidHeader, "misbehaviour Header_2 cannot be nil")
	}

	if m.Header1.TrustedHeight.RevisionHeight == 0 {
		return errorWithDetails(ErrInvalidHeaderHeight, "misbehaviour Header_1 cannot have zero revision height")
	}

	if m.Header2.TrustedHeight.RevisionHeight == 0 {
		return errorWithDetails(ErrInvalidHeaderHeight, "misbehaviour Header_2 cannot have zero revision height")
	}

	// ValidateBasic on both validators
	if err := m.Header1.ValidateBasic(); err != nil {
		return errorWithDetails(
			ErrInvalidMisbehaviour,
			ufmt.Sprintf("header 1 failed validation: %v", err),
		)
	}

	if err := m.Header2.ValidateBasic(); err != nil {
		return errorWithDetails(
			ErrInvalidMisbehaviour,
			ufmt.Sprintf("header 2 failed validation: %v", err),
		)
	}

	// Ensure that Height1 is greater than or equal to Height2
	if m.Header1.GetHeight().LT(m.Header2.GetHeight()) {
		return errorWithDetails(
			ErrInvalidMisbehaviour,
			ufmt.Sprintf("Header_1 height is less than Header_2 height (%s < %s)", m.Header1.GetHeight(), m.Header2.GetHeight()),
		)
	}

	return nil
}

package cometbls

import (
	"errors"

	"gno.land/p/onbloc/deps/encoding/proto"
	"gno.land/p/onbloc/deps/ics23"
)

// DecodeProofs decodes a protobuf-encoded MerkleProof (repeated CommitmentProof field 1).
func DecodeProofs(buf []byte) ([]ics23.CommitmentProof, error) {
	var out []ics23.CommitmentProof

	pos := 0

	for pos < len(buf) {
		fieldNum, wireType, newPos, err := decodeTag(buf, pos)
		if err != nil {
			return nil, err
		}

		pos = newPos

		if wireType != proto.LEN {
			pos, err = skipField(buf, pos, wireType)
			if err != nil {
				return nil, err
			}

			continue
		}

		s, newPos, err := proto.DecodeString(buf, pos)
		if err != nil {
			return nil, err
		}

		pos = newPos
		b := []byte(s)

		if fieldNum != 1 {
			continue
		}

		cp, err := decodeCommitmentProof(b)
		if err != nil {
			return nil, err
		}

		out = append(out, cp)
	}

	return out, nil
}

func decodeCommitmentProof(buf []byte) (ics23.CommitmentProof, error) {
	pos := 0

	for pos < len(buf) {
		fieldNum, wireType, newPos, err := decodeTag(buf, pos)
		if err != nil {
			return nil, err
		}

		pos = newPos

		if wireType != proto.LEN {
			pos, err = skipField(buf, pos, wireType)
			if err != nil {
				return nil, err
			}

			continue
		}

		s, newPos, err := proto.DecodeString(buf, pos)
		if err != nil {
			return nil, err
		}

		pos = newPos
		b := []byte(s)

		switch fieldNum {
		case 1:
			ep, err := decodeExistenceProof(b)
			if err != nil {
				return nil, err
			}

			return ics23.CommitmentProof_Exist{Exist: ep}, nil
		case 2:
			nep, err := decodeNonExistenceProof(b)
			if err != nil {
				return nil, err
			}

			return ics23.CommitmentProof_Nonexist{Nonexist: nep}, nil
		}
	}

	return nil, errors.New("empty commitment proof")
}

func decodeExistenceProof(buf []byte) (*ics23.ExistenceProof, error) {
	ep := &ics23.ExistenceProof{Path: make([]*ics23.InnerOp, 0, 32)}
	pos := 0

	for pos < len(buf) {
		fieldNum, wireType, newPos, err := decodeTag(buf, pos)
		if err != nil {
			return nil, err
		}

		pos = newPos

		switch {
		case (fieldNum == 1 || fieldNum == 2) && wireType == proto.LEN:
			s, newPos, err := proto.DecodeString(buf, pos)
			if err != nil {
				return nil, err
			}

			pos = newPos
			b := []byte(s)

			if fieldNum == 1 {
				ep.Key = b
			} else {
				ep.Value = b
			}

		case fieldNum == 3 && wireType == proto.LEN:
			s, newPos, err := proto.DecodeString(buf, pos)
			if err != nil {
				return nil, err
			}

			pos = newPos
			b := []byte(s)

			ep.Leaf, err = decodeLeafOp(b)
			if err != nil {
				return nil, err
			}
		case fieldNum == 4 && wireType == proto.LEN:
			s, newPos, err := proto.DecodeString(buf, pos)
			if err != nil {
				return nil, err
			}

			pos = newPos
			b := []byte(s)

			inner, err := decodeInnerOp(b)
			if err != nil {
				return nil, err
			}

			ep.Path = append(ep.Path, inner)
		default:
			pos, err = skipField(buf, pos, wireType)
			if err != nil {
				return nil, err
			}
		}
	}

	return ep, nil
}

func decodeLeafOp(buf []byte) (*ics23.LeafOp, error) {
	lop := &ics23.LeafOp{}
	pos := 0

	for pos < len(buf) {
		fieldNum, wireType, newPos, err := decodeTag(buf, pos)
		if err != nil {
			return nil, err
		}

		pos = newPos

		switch {
		case fieldNum >= 1 && fieldNum <= 4 && wireType == proto.VARINT:
			v, newPos, err := proto.DecodeVarint(buf, pos)
			if err != nil {
				return nil, err
			}

			pos = newPos

			switch fieldNum {
			case 1:
				lop.Hash = ics23.HashOp(v)
			case 2:
				lop.PrehashKey = ics23.HashOp(v)
			case 3:
				lop.PrehashValue = ics23.HashOp(v)
			case 4:
				lop.Length = ics23.LengthOp(v)
			}
		case fieldNum == 5 && wireType == proto.LEN:
			s, newPos, err := proto.DecodeString(buf, pos)
			if err != nil {
				return nil, err
			}

			pos = newPos
			b := []byte(s)
			lop.Prefix = b
		default:
			pos, err = skipField(buf, pos, wireType)
			if err != nil {
				return nil, err
			}
		}
	}

	return lop, nil
}

func decodeInnerOp(buf []byte) (*ics23.InnerOp, error) {
	iop := &ics23.InnerOp{}

	pos := 0
	for pos < len(buf) {
		fieldNum, wireType, newPos, err := decodeTag(buf, pos)
		if err != nil {
			return nil, err
		}

		pos = newPos

		switch {
		case fieldNum == 1 && wireType == proto.VARINT:
			v, newPos, err := proto.DecodeVarint(buf, pos)
			if err != nil {
				return nil, err
			}

			pos = newPos
			iop.Hash = ics23.HashOp(v)
		case (fieldNum == 2 || fieldNum == 3) && wireType == proto.LEN:
			s, newPos, err := proto.DecodeString(buf, pos)
			if err != nil {
				return nil, err
			}

			pos = newPos

			b := []byte(s)
			if fieldNum == 2 {
				iop.Prefix = b
			} else {
				iop.Suffix = b
			}
		default:
			pos, err = skipField(buf, pos, wireType)
			if err != nil {
				return nil, err
			}
		}
	}

	return iop, nil
}

func decodeNonExistenceProof(buf []byte) (*ics23.NonExistenceProof, error) {
	nep := &ics23.NonExistenceProof{}
	pos := 0

	for pos < len(buf) {
		fieldNum, wireType, newPos, err := decodeTag(buf, pos)
		if err != nil {
			return nil, err
		}

		pos = newPos
		if wireType != proto.LEN {
			pos, err = skipField(buf, pos, wireType)
			if err != nil {
				return nil, err
			}

			continue
		}

		s, newPos, err := proto.DecodeString(buf, pos)
		if err != nil {
			return nil, err
		}

		pos = newPos
		b := []byte(s)

		switch fieldNum {
		case 1:
			nep.Key = b
		case 2:
			ep, err := decodeExistenceProof(b)
			if err != nil {
				return nil, err
			}

			nep.Left = ep
		case 3:
			ep, err := decodeExistenceProof(b)
			if err != nil {
				return nil, err
			}

			nep.Right = ep
		}
	}

	return nep, nil
}

// decodeTag reads a protobuf tag at pos and splits it into the field number and
// wire type. It is built on top of proto.DecodeVarint.
func decodeTag(buf []byte, pos int) (fieldNum int, wireType proto.WireType, newPos int, err error) {
	tag, newPos, err := proto.DecodeVarint(buf, pos)
	if err != nil {
		return 0, 0, newPos, err
	}

	return int(tag >> 3), proto.WireType(tag & 0x7), newPos, nil
}

// skipField advances pos past a field whose value should be ignored, according
// to its wire type. Only the wire types used by the ICS23 proof messages are
// supported.
func skipField(buf []byte, pos int, wireType proto.WireType) (int, error) {
	switch wireType {
	case proto.VARINT:
		_, newPos, err := proto.DecodeVarint(buf, pos)

		return newPos, err
	case proto.LEN:
		_, newPos, err := proto.DecodeString(buf, pos)

		return newPos, err
	case proto.FIXED64:
		if pos+8 > len(buf) {
			return pos, errors.New("buffer underflow while skipping fixed64")
		}

		return pos + 8, nil
	case proto.FIXED32:
		if pos+4 > len(buf) {
			return pos, errors.New("buffer underflow while skipping fixed32")
		}

		return pos + 4, nil
	default:
		return pos, errors.New("unsupported wire type")
	}
}

package cometbls

import (
	"crypto/sha256"

	"gno.land/p/nt/ufmt/v0"
)

// MerkleRoot is the commitment root (app hash).
// Mirrors ibc.core.commitment.v1.MerkleRoot.
type MerkleRoot struct {
	Hash []byte
}

// GetHash implements RootI interface
func (mr MerkleRoot) GetHash() []byte {
	return mr.Hash
}

// Empty returns true if the root is empty
func (mr MerkleRoot) Empty() bool {
	return len(mr.GetHash()) == 0
}

// validateHash returns an error if the hash is not empty, but its
// size != tmhash.Size.
func validateHash(h []byte) error {
	if len(h) > 0 && len(h) != sha256.Size {
		return ufmt.Errorf(
			"expected size to be %d bytes, got %d bytes",
			sha256.Size,
			len(h),
		)
	}

	return nil
}

package cometbls

// maxChainIDLen bounds the source length. The original Solidity routine packs
// the identifier into a single EVM word, so it is never larger than 32 bytes.
const maxChainIDLen = 32

// chainIdToString converts a byte identifier into a string by trimming the
// leading zero padding and returning the remaining bytes. It returns an error
// when the source is empty, longer than maxChainIDLen, or contains only zero
// padding, since none of those yield a valid chain-id.
func chainIdToString(source []byte) (string, error) {
	if len(source) == 0 {
		return "", errorWithDetails(ErrInvalidChainID, "empty source")
	}

	if len(source) > maxChainIDLen {
		return "", errorWithDetails(ErrInvalidChainID, "source exceeds max length")
	}

	offset := 0
	for offset < len(source) && source[offset] == 0 {
		offset++
	}

	if offset == len(source) {
		return "", errorWithDetails(ErrInvalidChainID, "source is all zero padding")
	}

	return string(source[offset:]), nil
}

package ics23_mpt

import (
	"bytes"
	"crypto/keccak256"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/onbloc/ibc/union/lightclient"
	"gno.land/p/onbloc/ibc/union/types"
	"gno.land/p/onbloc/verifier/evm/storage"
)

// Sentinel errors for the object-form client. Proof-shape errors reuse the
// errors declared in consensus.gno (ErrConsensusStateTooShort,
// ErrInvalidCommitmentKey).
var (
	ErrNoL1Client              = errors.New("ics23mpt: l1 client not configured")
	ErrInvalidHeight           = errors.New("ics23mpt: proof height above latest height")
	ErrConsensusStateNotFound  = errors.New("ics23mpt: consensus state not found at height")
	ErrInvalidCommitmentValue  = errors.New("ics23mpt: commitment value must be 32 bytes")
	ErrStoredValueMismatch     = errors.New("ics23mpt: stored value mismatch")
	ErrMisbehaviourUnsupported = errors.New("ics23mpt: misbehaviour is not supported for state-lens clients")
)

// StateLensIcs23MptLightClient is the stateful object implementing
// lightclient.Interface for the state-lens/ics23/mpt client.
//
// It holds the client state and the L2 consensus states keyed by height.
// The L1 client dependency is resolved lazily on every use via getL1Client,
// mirroring Union's ctx-based approach where the light client struct is
// stateless and the host provides L1 access through the execution context.
//
// A state-lens client does not track its own chain directly. It trusts the
// counterparty's opaque L2 consensus blob, proven to exist in the L1 chain's
// state via the L1 light client. Membership of application state is then
// verified against the L2 storage root with EVM MPT storage proofs.
//
// This mirrors Union's StateLensIcs23MptLightClient
// (cosmwasm/lightclient/state-lens-ics23-mpt).
type StateLensIcs23MptLightClient struct {
	clientState            *ClientState
	consensusStateByHeight *bptree.BPTree // height:*ConsensusState
	// getL1ClientFn resolves the settlement-chain light client from the host store
	// on every call, so the state-lens always sees the current L1 state without
	// needing an explicit refresh step.
	getL1ClientFn func(types.ClientId) (lightclient.Interface, bool)
}

var _ lightclient.Interface = (*StateLensIcs23MptLightClient)(nil)

// NewStateLensIcs23MptLightClient builds the Gno object-form light client from
// decoded client and consensus state. getL1ClientFn is a live store getter
// called on every L1 lookup, matching Union's ctx-based approach where the
// light client resolves the L1 dependency lazily from the host store.
func NewStateLensIcs23MptLightClient(clientState *ClientState, consensusState *ConsensusState, getL1ClientFn func(types.ClientId) (lightclient.Interface, bool)) (*StateLensIcs23MptLightClient, error) {
	c := &StateLensIcs23MptLightClient{
		clientState:            clientState,
		consensusStateByHeight: bptree.NewBPTree32(),
		getL1ClientFn:          getL1ClientFn,
	}
	c.setConsensusState(clientState.L2LatestHeight, consensusState)
	return c, nil
}

// VerifyMembership verifies that key stores value under the L2 storage root at
// the given height using an EVM MPT storage proof. Status gating is the caller's
// responsibility, mirroring the cometbls object form.
// Union reference:
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/state-lens-ics23-mpt/src/client.rs#L39-L50
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/state-lens-ics23-mpt/src/client.rs#L189-L218
func (c *StateLensIcs23MptLightClient) VerifyMembership(height uint64, key []byte, proof []byte, value []byte) error {
	consensusState, storageProof, err := c.prepareProof(height, key, proof)
	if err != nil {
		return err
	}

	if len(value) != 32 {
		return ErrInvalidCommitmentValue
	}

	if !bytes.Equal(storageProof.Value, value) {
		return ErrStoredValueMismatch
	}

	// storage.VerifyProof only reads the storage root (it hashes the proof key
	// and walks the trie), so the root slice can be passed without copying.
	if err := storage.VerifyProof(consensusState.StorageRoot, storage.Proof{
		Key:   storageProof.Key,
		Value: storageProof.Value,
		Proof: storageProof.Proof,
	}); err != nil {
		return ufmt.Errorf("ics23mpt: storage membership verification failed: %v", err)
	}

	return nil
}

// VerifyNonMembership verifies the absence of key under the L2 storage root at
// the given height using an EVM MPT absence proof.
// Union reference:
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/state-lens-ics23-mpt/src/client.rs#L53-L63
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/state-lens-ics23-mpt/src/client.rs#L233-L254
func (c *StateLensIcs23MptLightClient) VerifyNonMembership(height uint64, key []byte, proof []byte) error {
	consensusState, storageProof, err := c.prepareProof(height, key, proof)
	if err != nil {
		return err
	}

	if err := storage.VerifyAbsence(consensusState.StorageRoot, storage.Proof{
		Key:   storageProof.Key,
		Proof: storageProof.Proof,
	}); err != nil {
		return ufmt.Errorf("ics23mpt: storage non-membership verification failed: %v", err)
	}

	return nil
}

// prepareProof performs the validation shared by VerifyMembership and
// VerifyNonMembership: the proof height must not exceed the latest height, a
// consensus state must exist at the height, the storage proof must decode, and
// its key must match the IBC commitment key derived from path.
// Union reference:
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/state-lens-ics23-mpt/src/client.rs#L189-L231
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/state-lens-ics23-mpt/src/client.rs#L233-L254
func (c *StateLensIcs23MptLightClient) prepareProof(height uint64, key []byte, proof []byte) (*ConsensusState, storage.Proof, error) {
	if height > c.clientState.L2LatestHeight {
		return nil, storage.Proof{}, ErrInvalidHeight
	}

	consensusState, found := c.getConsensusState(height)
	if !found {
		return nil, storage.Proof{}, ErrConsensusStateNotFound
	}

	storageProof, err := storage.DecodeProof(proof)
	if err != nil {
		return nil, storage.Proof{}, ufmt.Errorf("ics23mpt: invalid storage proof: %v", err)
	}

	if err := VerifyCommitmentKey(key, storageProof.Key); err != nil {
		return nil, storage.Proof{}, err
	}

	return consensusState, storageProof, nil
}

// VerifyHeader verifies a state-lens header and updates the client. It proves
// that the submitted L2 consensus state is committed in the L1 state at
// L1Height (via the L1 client), then extracts and stores the L2 consensus state
// at L2Height. Mirrors Union's verify_header.
// Union reference:
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/state-lens-ics23-mpt/src/client.rs#L98-L134
func (c *StateLensIcs23MptLightClient) VerifyHeader(caller address, headerBytes []byte, relayer address) (types.StateUpdate, error) {
	l1, ok := c.getL1ClientFn(types.ClientId(c.clientState.L1ClientID))
	if !ok {
		return types.StateUpdate{}, ErrNoL1Client
	}

	header, err := DecodeHeader(headerBytes)
	if err != nil {
		return types.StateUpdate{}, ufmt.Errorf("ics23mpt: failed to decode header: %v", err)
	}

	// The L2 consensus state must be committed under the consensus-state path of
	// the L2 client, in the L1 chain's state, as a keccak256 hash.
	consensusPath := types.ConsensusStatePath(types.ClientId(c.clientState.L2ClientID), types.NewHeight(header.L2Height))

	consensusHash := keccak256.Sum256(header.L2ConsensusState)
	if err := l1.VerifyMembership(header.L1Height, consensusPath[:], header.L2ConsensusStateProof, consensusHash[:]); err != nil {
		return types.StateUpdate{}, ufmt.Errorf("ics23mpt: l1 consensus state membership verification failed: %v", err)
	}

	consensusState, err := c.clientState.ExtractConsensusState(header.L2ConsensusState)
	if err != nil {
		return types.StateUpdate{}, err
	}

	return c.updateState(header, &consensusState), nil
}

// updateState stores the extracted L2 consensus state at L2Height and advances
// the latest height when the header is newer. Mirrors Union's StateUpdate flow.
func (c *StateLensIcs23MptLightClient) updateState(header Header, consensusState *ConsensusState) types.StateUpdate {
	height := header.L2Height

	c.setConsensusState(height, consensusState)

	stateUpdate := types.StateUpdate{Height: height}
	// Mirror the new consensus state bytes so the host (core) can persist them
	// for queries and counterparty proofs. Encoding cannot fail here (roots are
	// fixed 32-byte words), but stay defensive and leave the mirror empty on error.
	if consensusStateBytes, err := EncodeConsensusState(*consensusState); err == nil {
		stateUpdate.ConsensusStateBytes = consensusStateBytes
	}

	if height > c.clientState.L2LatestHeight {
		c.clientState.L2LatestHeight = height
		if clientStateBytes, err := EncodeClientState(*c.clientState); err == nil {
			stateUpdate.ClientStateBytes = clientStateBytes
		}
	}

	return stateUpdate
}

// VerifyCreation performs no creation-time state mutation; the state-lens client
// trusts its initial consensus state. Mirrors Union's verify_creation, which
// only emits an event.
// Union reference:
// https://github.com/unionlabs/union/blob/1bb07590230e7c4d071f32ad7185be021a1a1789/cosmwasm/lightclient/state-lens-ics23-mpt/src/client.rs#L83-L96
func (c *StateLensIcs23MptLightClient) VerifyCreation(caller address, relayer address) (types.ClientCreationResult, error) {
	return types.ClientCreationResult{}, nil
}

// Misbehaviour is unsupported for state-lens clients, mirroring Union's
// `unimplemented!()` for this client type.
func (c *StateLensIcs23MptLightClient) Misbehaviour(caller address, misbehaviour []byte, relayer address) ([]byte, error) {
	return nil, ErrMisbehaviourUnsupported
}

// GetTimestamp returns the timestamp of the consensus state at the latest
// height, or zero when none exists.
func (c *StateLensIcs23MptLightClient) GetTimestamp() types.Timestamp {
	consState, found := c.getConsensusState(c.clientState.L2LatestHeight)
	if !found {
		return 0
	}

	return types.Timestamp(consState.Timestamp)
}

func (c *StateLensIcs23MptLightClient) GetTimestampAtHeight(height uint64) (types.Timestamp, error) {
	consState, found := c.getConsensusState(height)
	if !found {
		return 0, ErrConsensusStateNotFound
	}

	return types.Timestamp(consState.Timestamp), nil
}

func (c *StateLensIcs23MptLightClient) GetLatestHeight() uint64 {
	return c.clientState.L2LatestHeight
}

func (c *StateLensIcs23MptLightClient) GetCounterpartyChainID() string {
	return c.clientState.L2ChainID
}

// Status mirrors the L1 client's status. A state-lens client has no liveness of
// its own: it is only as live as the L1 client it depends on. A missing or
// unknown L1 status is treated as Frozen, matching Union's unwrap_or(Frozen).
func (c *StateLensIcs23MptLightClient) Status() lightclient.Status {
	l1, ok := c.getL1ClientFn(types.ClientId(c.clientState.L1ClientID))
	if !ok {
		return lightclient.Frozen
	}

	switch status := l1.Status(); status {
	case lightclient.Active, lightclient.Expired, lightclient.Frozen:
		return status
	default:
		return lightclient.Frozen
	}
}

func (c *StateLensIcs23MptLightClient) getConsensusState(height uint64) (*ConsensusState, bool) {
	v := c.consensusStateByHeight.Get(heightKey(height))
	if v == nil {
		return nil, false
	}

	consState, ok := v.(*ConsensusState)
	if !ok {
		return nil, false
	}

	return consState, true
}

func (c *StateLensIcs23MptLightClient) setConsensusState(height uint64, consState *ConsensusState) {
	c.consensusStateByHeight.Set(heightKey(height), consState)
}

// heightKey renders a height as a fixed-width, lexicographically sortable bptree
// key. ibc-union heights carry a single revision, so the numeric ordering of the
// formatted height matches height ordering.
func heightKey(height uint64) string {
	return zeroPadDecimalUint64(height)
}

// zeroPadDecimalUint64 converts a uint64 number into a zero-padded 20-character string.
func zeroPadDecimalUint64(num uint64) string {
	s := strconv.FormatUint(num, 10)
	zerosNeeded := 20 - len(s)

	return strings.Repeat("0", zerosNeeded) + s
}

package ics23_mpt

import (
	"bytes"
	"encoding/binary"
	"errors"

	"gno.land/p/onbloc/verifier/evm/storage"
)

var (
	ErrConsensusStateTooShort = errors.New("ics23mpt: l2 consensus state too short")
	ErrInvalidCommitmentKey   = errors.New("ics23mpt: invalid commitment key")
)

// ExtractConsensusState parses the L2 consensus state bytes into a
// ConsensusState using the byte offsets recorded in this client state. The
// state-lens client trusts the counterparty's opaque L2 consensus blob and
// reads timestamp / state root / storage root from fixed offsets.
func (cs ClientState) ExtractConsensusState(data []byte) (ConsensusState, error) {
	timestamp, err := extractUint64(data, int(cs.TimestampOffset))
	if err != nil {
		return ConsensusState{}, err
	}

	stateRoot, err := extractBytes32(data, int(cs.StateRootOffset))
	if err != nil {
		return ConsensusState{}, err
	}

	storageRoot, err := extractBytes32(data, int(cs.StorageRootOffset))
	if err != nil {
		return ConsensusState{}, err
	}

	return ConsensusState{
		Timestamp:   timestamp,
		StateRoot:   stateRoot,
		StorageRoot: storageRoot,
	}, nil
}

func extractUint64(data []byte, offset int) (uint64, error) {
	if offset < 0 || offset+8 > len(data) {
		return 0, ErrConsensusStateTooShort
	}

	return binary.BigEndian.Uint64(data[offset : offset+8]), nil
}

func extractBytes32(data []byte, offset int) ([]byte, error) {
	if offset < 0 || offset+32 > len(data) {
		return nil, ErrConsensusStateTooShort
	}

	out := make([]byte, 32)
	copy(out, data[offset:offset+32])

	return out, nil
}

// VerifyCommitmentKey checks that proofKey matches the IBC commitment key
// derived from path. It rejects proofs whose key does not bind to the
// expected commitment path.
func VerifyCommitmentKey(path []byte, proofKey []byte) error {
	expected, err := storage.IBCCommitmentKey(path)
	if err != nil {
		return ErrInvalidCommitmentKey
	}

	if !bytes.Equal(expected[:], proofKey) {
		return ErrInvalidCommitmentKey
	}

	return nil
}

package ics23_mpt

import (
	"errors"

	abienc "gno.land/p/onbloc/encoding/abi"
)

var (
	clientStateSchema = abienc.Schema{Fields: []abienc.Field{
		{Type: abienc.TypeString},
		{Type: abienc.TypeUint32},
		{Type: abienc.TypeUint32},
		{Type: abienc.TypeUint64},
		{Type: abienc.TypeUint32},
		{Type: abienc.TypeUint32},
		{Type: abienc.TypeUint32},
	}}

	consensusStateSchema = abienc.Schema{Fields: []abienc.Field{
		{Type: abienc.TypeUint64},
		{Type: abienc.TypeBytes32},
		{Type: abienc.TypeBytes32},
	}}

	headerSchema = abienc.Schema{Fields: []abienc.Field{
		{Type: abienc.TypeUint64},
		{Type: abienc.TypeUint64},
		{Type: abienc.TypeBytes},
		{Type: abienc.TypeBytes},
	}}
)

func EncodeClientState(cs ClientState) ([]byte, error) {
	return abienc.Encode(clientStateSchema, []any{
		cs.L2ChainID,
		cs.L1ClientID,
		cs.L2ClientID,
		uint64(cs.L2LatestHeight),
		uint32(cs.TimestampOffset),
		uint32(cs.StateRootOffset),
		uint32(cs.StorageRootOffset),
	})
}

func DecodeClientState(buf []byte) (ClientState, error) {
	vals, err := abienc.Decode(clientStateSchema, buf)
	if err != nil {
		return ClientState{}, wrapErr(err)
	}

	timestampOffset, err := toUint16(vals[4].(uint32), "timestamp offset")
	if err != nil {
		return ClientState{}, err
	}

	stateRootOffset, err := toUint16(vals[5].(uint32), "state root offset")
	if err != nil {
		return ClientState{}, err
	}

	storageRootOffset, err := toUint16(vals[6].(uint32), "storage root offset")
	if err != nil {
		return ClientState{}, err
	}

	return ClientState{
		L2ChainID:         vals[0].(string),
		L1ClientID:        vals[1].(uint32),
		L2ClientID:        vals[2].(uint32),
		L2LatestHeight:    vals[3].(uint64),
		TimestampOffset:   timestampOffset,
		StateRootOffset:   stateRootOffset,
		StorageRootOffset: storageRootOffset,
	}, nil
}

func EncodeConsensusState(cs ConsensusState) ([]byte, error) {
	stateRoot, err := toBytes32(cs.StateRoot, "state root")
	if err != nil {
		return nil, err
	}

	storageRoot, err := toBytes32(cs.StorageRoot, "storage root")
	if err != nil {
		return nil, err
	}

	return abienc.Encode(consensusStateSchema, []any{
		cs.Timestamp,
		stateRoot,
		storageRoot,
	})
}

func DecodeConsensusState(buf []byte) (ConsensusState, error) {
	vals, err := abienc.Decode(consensusStateSchema, buf)
	if err != nil {
		return ConsensusState{}, wrapErr(err)
	}

	stateRoot := vals[1].([32]byte)
	storageRoot := vals[2].([32]byte)

	return ConsensusState{
		Timestamp:   vals[0].(uint64),
		StateRoot:   cloneBytes(stateRoot[:]),
		StorageRoot: cloneBytes(storageRoot[:]),
	}, nil
}

func EncodeHeader(h Header) ([]byte, error) {
	return abienc.Encode(headerSchema, []any{
		uint64(h.L1Height),
		uint64(h.L2Height),
		h.L2ConsensusStateProof,
		h.L2ConsensusState,
	})
}

func DecodeHeader(buf []byte) (Header, error) {
	vals, err := abienc.Decode(headerSchema, buf)
	if err != nil {
		return Header{}, wrapErr(err)
	}

	return Header{
		L1Height:              vals[0].(uint64),
		L2Height:              vals[1].(uint64),
		L2ConsensusStateProof: vals[2].([]byte),
		L2ConsensusState:      vals[3].([]byte),
	}, nil
}

// wrapErr prefixes a wrapped decode error with the package domain.
func wrapErr(err error) error {
	return errors.New("ics23mpt: " + err.Error())
}

func toUint16(v uint32, name string) (uint16, error) {
	if v > 0xFFFF {
		return 0, errors.New("ics23mpt: " + name + " exceeds uint16")
	}

	return uint16(v), nil
}

func toBytes32(b []byte, name string) ([32]byte, error) {
	if len(b) != 32 {
		return [32]byte{}, errors.New("ics23mpt: " + name + " must be 32 bytes")
	}

	var out [32]byte
	copy(out[:], b)

	return out, nil
}

func cloneBytes(b []byte) []byte {
	out := make([]byte, len(b))
	copy(out, b)

	return out
}

package ics23_mpt

const ClientType = "state-lens/ics23/mpt"

// ClientState mirrors Union's state-lens ClientState<ics23-mpt Extra>.
//
// The generic Rust form is flattened here:
//
//	(string,uint32,uint32,uint64,uint16,uint16,uint16)
//
// L1ClientID is the client on this chain tracking the settlement chain.
// L2ClientID is the client on the settlement chain tracking the chain whose
// state this state-lens client exposes.
type ClientState struct {
	L2ChainID         string
	L1ClientID        uint32
	L2ClientID        uint32
	L2LatestHeight    uint64
	TimestampOffset   uint16
	StateRootOffset   uint16
	StorageRootOffset uint16
}

// ConsensusState mirrors state-lens-ics23-mpt ConsensusState.
type ConsensusState struct {
	Timestamp   uint64 // nanoseconds since Unix epoch
	StateRoot   []byte // bytes32
	StorageRoot []byte // bytes32
}

// Header is the state-lens ClientMessage used to update the client.
type Header struct {
	L1Height              uint64
	L2Height              uint64
	L2ConsensusStateProof []byte
	L2ConsensusState      []byte
}

